scripts.code:
// ==== 設定・PC とのつながり (仕様 8.1 / 8.4 / 8.6 / 11.3) ====
// 考えること (会話・ヒント・答え合わせ・ノートを読む・声) は、同じ LAN の PC で動く「Cohabit PC」(tmp/CohabitPC) がする。
// タブレットと同じ「PC の先生」(/tablet/api/*) を使うので、教科は決めない。
// PC は自動で探す: 前につながったアドレス → CONFIG.server → 同じネットワーク (/24) を順に探す。見つけたら覚える。
// アドレスを手で入れる (設定 → アドレス変更) のは、どうしても見つからないときだけ。
// 方針: 性能より安定。通信には必ず時間切れがあり、用事ごとに同時に 1 本だけ。PC が無くても勉強は続けられる。
var CONFIG = {
  server: 'http://192.168.0.12:8000', // 最初に試す PC。見つからなければ、このアドレスの /24 を探す
  port: 8000,
  token: '',            // PC アプリで合言葉を決めたときだけ
  character: 'Sister',
  chatModel: 'cohabit-chat',     // PC アプリが、PC の設定のモデルに置き換える
  visionModel: 'cohabit-vision', // 画像入力に対応したモデル (PC の設定)
  sttModel: 'whisper-1',
  ttsModel: 'tts-1', ttsVoice: 'nova',
};

// ---- 小物 ----
function nowIso() { return new Date().toISOString(); }
function secondsSince(iso) { return iso ? (Date.now() - new Date(iso).getTime()) / 1000 : Infinity; }
function clip(text, n) { text = String(text == null ? '' : text); return text.length > n ? text.slice(0, n - 1) + '…' : text; }
function errText(e) { return e && e.message ? e.message : String(e); }
// 例外を外に出さない (タイマー・通信・ボタンの中で使う)。同じ場所の失敗は 1 分に 1 回だけログに出す
var ERROR_LOGGED = {};
function attempt(label, fn) {
  try { return fn(); } catch (e) {
    var now = Date.now();
    if (!ERROR_LOGGED[label] || now - ERROR_LOGGED[label] > 60000) { ERROR_LOGGED[label] = now; error(label + ': ' + errText(e)); }
    return undefined;
  }
}
function safe(label, fn) { return function () { var self = this, args = arguments; return attempt(label, function () { return fn.apply(self, args); }); }; }
function later(label, ms, fn) { return setTimeout(safe(label, fn), ms); }
// LLM の返事から最初の JSON を取り出す (前後に文章が付いていても読む)
function firstJson(text) {
  if (!text) return null;
  var start = text.indexOf('{');
  var end = text.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (e) { return null; }
}
function replyText(r) {
  return r && r.ok && r.json && r.json.choices && r.json.choices[0] && r.json.choices[0].message ? r.json.choices[0].message.content : null;
}
var HAS = {
  room: typeof room !== 'undefined', controller: typeof controller !== 'undefined', hands: typeof hands !== 'undefined',
  mic: typeof mic !== 'undefined', headset: typeof headset !== 'undefined', camera: typeof camera !== 'undefined',
  vrm: typeof vrm !== 'undefined', audio: typeof audio !== 'undefined',
};
function sisterHere() { return HAS.vrm && attempt('vrm.exists', function () { return vrm.exists(CONFIG.character); }) === true; }

// ---- 利用者が決めること (端末に残る: settings.*) ----
var Settings = {
  get: function (key, fallback) { var v = store.get('settings.' + key); return v === null || v === undefined ? fallback : v; },
  set: function (key, value) { store.set('settings.' + key, value); if (typeof Panel !== 'undefined') attempt('panel.refresh', Panel.refresh); },
};

function authHeaders() { var h = {}; if (CONFIG.token) h['X-Cohabit-Token'] = CONFIG.token; return h; }
function url(path) { return PC.base + path; }
function shortServer() { return (PC.base || PC.known()).replace(/^https?:\/\//, ''); }

// ---- 通信: 用事ごとに同時に 1 本、必ず時間切れ、返事の中の例外は外に出さない ----
var Net = {
  busy: {},
  call: function (purpose, opts, fn) {
    if (Net.busy[purpose]) return false;
    Net.busy[purpose] = true;
    var done = false;
    var finish = function (r) {
      if (done) return;
      done = true;
      Net.busy[purpose] = false;
      if (fn) attempt('net ' + purpose, function () { fn(r || { ok: false, status: 0, error: 'noReply' }); });
    };
    opts.timeout = opts.timeout || 10;
    if (!opts.headers) opts.headers = authHeaders();
    // 返事が来ないまま残らないように見張る (時間切れ + 5 秒)
    var watchdog = setTimeout(function () { if (!done) { log('net ' + purpose + ': no reply; giving up'); finish({ ok: false, status: 0, error: 'watchdog' }); } }, (opts.timeout + 5) * 1000);
    try {
      api.request(opts, function (r) { clearTimeout(watchdog); finish(r); });
    } catch (e) {
      clearTimeout(watchdog);
      finish({ ok: false, status: 0, error: errText(e) });
    }
    return true;
  },
  isBusy: function (purpose) { return !!Net.busy[purpose]; },
};

// ---- LLM を使う用事 ----
// 頼まれた用事 (声・ヒント・採点・問題) は同時に 1 本。2 つまで順に待たせる (3 つ目が来たら、いちばん古いものをやめる)。
// 裏の用事 (手が止まったときのノート確認・机の物) は、ほかに何も無いときだけ 1 本。裏の用事が走っていても、頼まれた用事は
// 待たずに送る (PC の側で頼まれた用事を先に回す)。
var Llm = {
  busy: null,      // 頼まれた用事の名前
  busySince: 0,
  bg: null,        // 裏の用事の名前
  bgSince: 0,
  waiting: [],
  idle: function () { return !Llm.busy && !Llm.bg && !Llm.waiting.length; },
  run: function (purpose, opts, fn, userAsked) {
    if (!PC.online) { attempt('llm ' + purpose, function () { fn({ ok: false, status: 0, error: 'offline' }); }); return true; }
    if (!userAsked) {
      if (!Llm.idle() || Net.isBusy('stt')) return false; // 声を文字にしている間も、裏の用事は始めない
      Llm.bg = purpose;
      Llm.bgSince = Date.now();
      var ok = Net.call('llm-bg', opts, function (r) { Llm.bg = null; Stage.render(); attempt('llm ' + purpose, function () { fn(r); }); });
      if (!ok) Llm.bg = null;
      Stage.render();
      return ok;
    }
    if (Llm.busy) {
      Llm.waiting.push({ purpose: purpose, opts: opts, fn: fn });
      if (Llm.waiting.length > 2) {
        var old = Llm.waiting.shift();
        attempt('llm superseded', function () { old.fn({ ok: false, status: 0, error: 'superseded' }); });
      }
      return true;
    }
    Llm.busy = purpose;
    Llm.busySince = Date.now();
    Stage.render();
    var started = Net.call('llm', opts, function (r) {
      Llm.busy = null;
      if (!r.ok && r.error !== 'superseded') Stage.fail(r);
      Stage.render();
      attempt('llm ' + purpose, function () { fn(r); });
      var next = Llm.waiting.shift();
      if (next) Llm.run(next.purpose, next.opts, next.fn, true);
    });
    if (!started) { Llm.busy = null; attempt('llm ' + purpose, function () { fn({ ok: false, status: 0, error: 'busy' }); }); }
    return true;
  },
};

// ---- PC を探す・つながりを見る ----
// 状態: searching (探している) / online / notFound (一通り探して見つからない。少し間を空けて探し続ける)
var PC = {
  base: '',
  online: false,
  state: 'searching',
  lastOk: 0,
  fails: 0,
  checking: false,
  scanning: false,
  scanId: 0,
  lastScanAt: 0,
  nextCheckAt: 0,
  inference: '',
  inferenceShort: '',
  where: {},
  allowImages: true,
  wearing: true,
  presenceSent: null,
  listeners: [],

  onOnline: function (fn) { PC.listeners.push(fn); },
  known: function () { return String(Settings.get('server', CONFIG.server) || CONFIG.server).replace(/\/+$/, ''); },
  normalize: function (text) {
    text = String(text || '').trim().replace(/\s+/g, '').replace(/\/+$/, '');
    if (!text) return '';
    if (!/^https?:\/\//.test(text)) text = 'http://' + text;
    if (!/:\d+$/.test(text.replace(/^https?:\/\//, ''))) text += ':' + CONFIG.port;
    return text;
  },

  // 1 か所に聞く。Cohabit PC なら fn(json)、違えば fn(null)。たくさん同時に聞く (探す) ので Net は通さない
  probe: function (base, timeout, fn) {
    var done = false;
    var finish = function (json) { if (done) return; done = true; attempt('pc.probe', function () { fn(json); }); };
    var watchdog = setTimeout(function () { finish(null); }, (timeout + 4) * 1000);
    try {
      api.request({ url: base + '/health', method: 'GET', headers: authHeaders(), responseType: 'json', timeout: timeout }, function (r) {
        clearTimeout(watchdog);
        finish(r && r.ok && r.json && r.json.app === 'cohabit-pc' ? r.json : null);
      });
    } catch (e) { clearTimeout(watchdog); finish(null); }
  },

  // 毎秒から呼ぶ。実際に聞くのは、つながっていれば 10 秒ごと、切れていれば 5 秒ごと
  tick: function () {
    var now = Date.now();
    if (PC.online && PC.presenceSent !== PC.wearing) PC.sendPresence();
    if (PC.checking || PC.scanning || now < PC.nextCheckAt) return;
    if (PC.online) { PC.nextCheckAt = now + 10000; PC.health(); return; }
    PC.nextCheckAt = now + 5000;
    PC.tryKnown();
  },

  health: function () {
    PC.checking = true;
    PC.probe(PC.base, 4, function (json) {
      PC.checking = false;
      if (json) { PC.fails = 0; PC.accept(PC.base, json); return; }
      PC.fails += 1;
      if (PC.fails >= 2) PC.lost(); // 1 回の取りこぼしでは切れたことにしない
      else PC.nextCheckAt = Date.now() + 3000;
    });
  },

  // 覚えているアドレスを順に試す。だめなら (1 分に 1 回まで) 同じネットワークを探す
  tryKnown: function () {
    var list = [];
    [PC.base, PC.known(), PC.normalize(CONFIG.server)].forEach(function (b) { if (b && list.indexOf(b) < 0) list.push(b); });
    PC.checking = true;
    var i = 0;
    var next = function () {
      if (PC.online) { PC.checking = false; return; }
      if (i >= list.length) {
        PC.checking = false;
        if (Date.now() - PC.lastScanAt >= 60000) PC.scan(list[0]);
        else if (PC.state !== 'notFound' && PC.lastScanAt) { PC.state = 'notFound'; Hud.pc(); }
        return;
      }
      var base = list[i++];
      PC.probe(base, 2, function (json) { if (json) { PC.checking = false; PC.accept(base, json); } else next(); });
    };
    next();
  },

  // 同じ /24 を、最後のアドレスに近い順に 16 台ずつ聞く (1 台 1 秒で時間切れ。全部で 20 秒くらい)
  scan: function (around) {
    var m = /^(https?:\/\/)(\d+)\.(\d+)\.(\d+)\.(\d+)(?::(\d+))?$/.exec(around || '');
    PC.lastScanAt = Date.now();
    if (!m) { PC.state = 'notFound'; Hud.pc(); return; }
    var prefix = m[1] + m[2] + '.' + m[3] + '.' + m[4] + '.';
    var port = m[6] || String(CONFIG.port);
    var last = +m[5];
    var hosts = [];
    for (var d = 1; d < 254; d++) {
      if (last - d >= 1) hosts.push(last - d);
      if (last + d <= 254) hosts.push(last + d);
    }
    var id = ++PC.scanId;
    PC.scanning = true;
    PC.state = 'searching';
    Hud.pc();
    log('PC: scanning ' + prefix + '1-254:' + port);
    var pos = 0;
    var batch = function () {
      if (id !== PC.scanId || PC.online) { PC.scanning = false; return; }
      if (pos >= hosts.length) {
        PC.scanning = false;
        PC.state = 'notFound';
        Hud.pc();
        log('PC: not found on ' + prefix + '0/24');
        if (!PC.toldNotFound) { PC.toldNotFound = true; Hud.notice('PC で Cohabit PC を起動すると、自動でつながります', 20); }
        return;
      }
      var group = hosts.slice(pos, pos + 16);
      pos += group.length;
      var left = group.length;
      var found = null;
      group.forEach(function (h) {
        var base = prefix + h + ':' + port;
        PC.probe(base, 1, function (json) {
          if (json && !found) found = { base: base, json: json };
          left -= 1;
          if (left > 0) return;
          if (id !== PC.scanId) return;
          if (found) { PC.scanning = false; PC.accept(found.base, found.json); }
          else later('pc.scan', 50, batch);
        });
      });
    };
    batch();
  },

  accept: function (base, json) {
    var was = PC.online;
    PC.base = base;
    PC.online = true;
    PC.state = 'online';
    PC.lastOk = Date.now();
    PC.scanId++;
    PC.nextCheckAt = Date.now() + 10000;
    PC.inference = json.inference && json.inference.text ? json.inference.text : '';
    PC.inferenceShort = inferenceShort(json.inference);
    PC.where = {};
    var parts = json.inference && json.inference.parts || {};
    for (var k in parts) PC.where[k] = parts[k] && parts[k].where;
    PC.allowImages = json.allowImages !== false;
    if (PC.known() !== base) Settings.set('server', base);
    Hud.pc();
    if (!was) {
      log('PC connected: ' + base);
      Hud.notice('PC につながりました (' + shortServer() + ')', 6);
      PC.presenceSent = null;
      Report.event('session', { what: 'pc_online', text: 'PC につながった' });
      PC.listeners.forEach(function (fn) { attempt('pc.onOnline', fn); });
    }
  },

  lost: function () {
    if (!PC.online) return;
    PC.online = false;
    PC.state = 'searching';
    PC.fails = 0;
    PC.nextCheckAt = Date.now() + 3000;
    log('PC lost: ' + PC.base);
    Hud.pc();
  },

  // 設定パネルでアドレスを入れた / 「PC を探し直す」
  useAddress: function (text) {
    var base = PC.normalize(text);
    if (!base) return;
    Settings.set('server', base);
    PC.lost();
    PC.base = base;
    PC.scanId++;
    PC.scanning = false;
    PC.lastScanAt = 0;
    PC.nextCheckAt = 0;
    PC.state = 'searching';
    Hud.pc();
  },
  rescan: function () {
    PC.lost();
    PC.scanId++;
    PC.scanning = false;
    PC.lastScanAt = 0;
    PC.nextCheckAt = 0;
    PC.state = 'searching';
    Hud.pc();
  },

  // ヘッドセットをかぶった / 外した (タブレットの妹が引っ込む / 出てくる)
  setWearing: function (on) { PC.wearing = !!on; if (PC.online) PC.sendPresence(); },
  sendPresence: function () {
    var value = PC.wearing;
    Net.call('presence', { url: url('/tablet/api/presence'), method: 'POST', json: { wearing: value }, responseType: 'json', timeout: 4 }, function (r) {
      if (r.ok) PC.presenceSent = value;
    });
  },
};

// 「会話: クラウド / 声: この PC / 判断: この PC」(HUD の 1 行。仕様 11.3)
var WHERE_JA = { this_pc: 'この PC', lan: 'LAN の PC', cloud: 'クラウド', off: '使わない' };
function inferenceShort(inf) {
  if (!inf) return '';
  if (!inf.parts) return inf.text || '';
  var w = function (k) { var p = inf.parts[k]; return p ? (WHERE_JA[p.where] || p.where) : '?'; };
  var lev = inf.parts.lev && inf.parts.lev.where !== 'off' ? w('lev') : '端末の決まり';
  return '会話: ' + w('chat') + ' / 声: ' + w('tts') + ' / 判断: ' + lev;
}

// ---- PC の画面へ記録を送る (仕様 8.4 の形。画像・音声は入れない) ----
var SESSION_ID = 'ses_' + Date.now().toString(36);
var Report = {
  queue: [],
  status: null, // 状態のまとめを返す関数 (「一緒に勉強」が入れる)

  event: function (type, payload, confidence, sensor) {
    Report.queue.push({
      event_id: 'evt_' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36),
      session_id: SESSION_ID, observed_at: nowIso(), sensor: sensor || 'quest_app', type: type,
      payload: payload || {}, confidence: confidence == null ? null : confidence,
    });
    if (Report.queue.length > 200) Report.queue = Report.queue.slice(Report.queue.length - 200);
  },

  flush: function () {
    if (!PC.online || Net.isBusy('observe')) return;
    if (Report.status) attempt('report.status', function () { Report.event('status', Report.status()); });
    var batch = Report.queue.slice(0, 60);
    Report.queue = Report.queue.slice(batch.length);
    Net.call('observe', { url: url('/observe'), method: 'POST', json: { events: batch }, responseType: 'json', timeout: 8 }, function (r) {
      if (!r.ok) Report.queue = batch.filter(function (e) { return e.type !== 'status'; }).concat(Report.queue).slice(-200);
    });
  },
};

// ---- PC の画面の操作ボタンを受ける ----
var Control = {
  after: null,
  handlers: {},
  on: function (name, fn) { Control.handlers[name] = fn; },

  poll: function () {
    if (!PC.online || Net.isBusy('control')) return;
    Net.call('control', { url: url('/control/next?after=' + (Control.after == null ? 0 : Control.after)), method: 'GET', responseType: 'json', timeout: 4 }, function (r) {
      if (!r.ok || !r.json) return;
      var latest = r.json.latest || 0;
      // 初めて / PC アプリが起動し直した: 前に押されたものは動かさない
      if (Control.after == null || latest < Control.after) { Control.after = latest; return; }
      (r.json.commands || []).forEach(function (c) {
        Control.after = Math.max(Control.after, c.id);
        var fn = Control.handlers[c.command];
        if (!fn) { log('PC control: not used on the Quest: ' + c.command); return; }
        log('PC control: ' + c.command);
        attempt('PC control ' + c.command, function () { fn(c.args || {}); });
      });
      Control.after = Math.max(Control.after, latest);
    });
  },
};

// ---- 視界の表示 (HUD) ----
var Hud = {
  guideTimer: null,
  noticeTimer: null,
  pc: function () {
    var text, color;
    if (PC.online) { text = '● PC 接続中'; color = '#7be0a6'; }
    else if (PC.state === 'notFound') { text = '● PC が見つかりません'; color = '#ffb86b'; }
    else { text = '● PC を探しています…'; color = '#ffd27a'; }
    store.set('hud.pc', text);
    ui.setColor('pcText', color);
    // 推論の実行先を出す。Quest の中だけで完結しているとは言わない (仕様 11.3)
    store.set('cohabit.backend', PC.online ? '推論 — ' + PC.inferenceShort
      : 'PC が来るまで、ヒントと答え合わせはお休み');
  },
  guide: function (text, seconds) {
    store.set('hud.guide', text);
    if (Hud.guideTimer) clearTimeout(Hud.guideTimer);
    Hud.guideTimer = seconds ? later('hud.guide', seconds * 1000, function () { store.set('hud.guide', ''); }) : null;
  },
  notice: function (text, seconds) {
    store.set('hud.notice', text);
    if (Hud.noticeTimer) clearTimeout(Hud.noticeTimer);
    Hud.noticeTimer = seconds ? later('hud.notice', seconds * 1000, function () { store.set('hud.notice', ''); }) : null;
  },
};

// ---- 今どこまで進んでいるか (HUD の字幕の上の 1 行。PC の画面にも status.stage で出る) ----
// マイク (状態と音量) | 話しています… / 文字にしています… n秒 / あなた: … / 考え中… n秒 (何を) / 順番待ち / 妹が話しています / 失敗の短い知らせ
var LLM_JA = { problem: '問題を作っています', ask: 'ヒント・説明', answer: '採点', check: 'ノートを見ています', chat: 'おしゃべり', glance: '机を見ています' };
var MIC_JA = { off: 'オフ', permission: '許可待ち', denied: '許可されていない', noDevice: 'マイクが無い', failed: '開けない', on: '聞いています' };
var Stage = {
  sttSince: 0,
  heard: null,      // { text, until }
  error: null,      // { text, until }
  last: '',
  kind: 'idle',

  micStatus: function () {
    if (!HAS.mic) return 'noDevice';
    if (!Settings.get('mic', true)) return 'off';
    var st = attempt('mic.status', function () { return mic.status ? mic.status() : (store.get('mic.active') ? 'on' : 'off'); });
    return st || 'off';
  },
  micLevel: function () {
    if (!HAS.mic) return 0;
    var v = attempt('mic.level', function () { return mic.level ? mic.level() : store.get('mic.level'); });
    return typeof v === 'number' ? v : 0;
  },
  bar: function (level) {
    var n = Math.max(0, Math.min(5, Math.round(level * 5)));
    return '●●●●●'.slice(0, n) + '・・・・・'.slice(0, 5 - n);
  },
  sttBegin: function () { Stage.sttSince = Date.now(); Stage.render(); },
  sttEnd: function (text, r) {
    Stage.sttSince = 0;
    if (text) Stage.heard = { text: 'あなた: 「' + clip(text, 30) + '」', until: Date.now() + 6000 };
    else Stage.heard = { text: r && !r.ok ? '聞き取れなかった (' + Stage.errText(r) + ')' : '聞き取れなかった', until: Date.now() + 6000 };
    Stage.render();
  },
  errText: function (r) {
    if (!PC.online || (r && r.error === 'offline')) return 'PC につながっていない';
    if (r && r.status === 429) return 'LLM の回数制限。少し待って';
    if (r && (r.status === 0 || r.error === 'watchdog')) return 'PC から返事が無い';
    if (r && r.status >= 500) return 'LLM が答えない';
    return 'うまくいかなかった' + (r && r.status ? ' (' + r.status + ')' : '');
  },
  fail: function (r) { Stage.error = { text: '× ' + Stage.errText(r), until: Date.now() + 8000 }; Stage.render(); },
  secs: function (since) { return Math.max(0, Math.round((Date.now() - since) / 1000)) + '秒'; },

  activity: function () {
    var now = Date.now();
    if (Stage.sttSince) { Stage.kind = 'stt'; return '文字にしています… ' + Stage.secs(Stage.sttSince); }
    if (HAS.mic && Settings.get('mic', true) && (attempt('mic.speaking', function () { return mic.speaking ? mic.speaking() : store.get('mic.speaking'); }))) { Stage.kind = 'listening'; return '話しています…'; }
    var heard = Stage.heard && now < Stage.heard.until ? Stage.heard.text : '';
    if (Llm.busy) {
      Stage.kind = 'llm';
      return (heard ? clip(heard, 16) + ' → ' : '') + '考え中… ' + Stage.secs(Llm.busySince) + ' (' + (LLM_JA[Llm.busy] || Llm.busy) + ')' + (Llm.waiting.length ? ' · 順番待ち ' + Llm.waiting.length : '');
    }
    if (heard) { Stage.kind = 'heard'; return heard; }
    if (Voice.speaking) { Stage.kind = 'speaking'; return Voice.handle ? '妹が話しています' : '妹が話しています (字幕)'; }
    if (Stage.error && now < Stage.error.until) { Stage.kind = 'error'; return Stage.error.text; }
    if (Llm.bg) { Stage.kind = 'background'; return '(裏で' + (LLM_JA[Llm.bg] || Llm.bg) + ' ' + Stage.secs(Llm.bgSince) + ')'; }
    Stage.kind = 'idle';
    return '';
  },
  text: function () {
    var st = Stage.micStatus();
    var micPart = 'マイク ' + (st === 'on' ? Stage.bar(Stage.micLevel()) : (MIC_JA[st] || st));
    var act = attempt('stage.activity', Stage.activity) || '';
    return micPart + (act ? '  |  ' + act : '');
  },
  render: function () {
    var t = attempt('stage.text', Stage.text);
    if (t != null && t !== Stage.last) { Stage.last = t; store.set('hud.stage', t); }
  },
};

attempt('startup', function () {
  scene.setVisible('Quiz', false);
  scene.setVisible('Settings', false);
  scene.setVisible('Consent', false);
  scene.setVisible('Address', false);
  ui.setVisibility('subtitlePlate', false);
  store.set('talk.line', '');
  store.set('cohabit.sending', '');
  store.set('hud.notice', '');
  Hud.pc();
});

// ==== 記憶 (仕様 7.3 / 5.5 / 11.4 / 24.1 / 25) ====
// 端末に残すのは「妹として覚えていること」(出来事・物・関係・席) だけ。学習記録・苦手の要約は PC が持つ (タブレットと共通)。
// どの記録にも「いつ・何から分かったか・どれくらい確か」を付ける。記憶に無いことは話さない (仕様 15.1)。
// 「長い記憶」を切ると、新しい出来事はこのセッションの間だけ覚え、端末には残さない (仕様 25)。
var EVENT_JA = {
  session_started: '会えた', session_paused: 'ヘッドセットが外された', session_resumed: 'また会えた',
  study_started: '勉強を始めた', study_paused: '勉強を中断した', study_ended: '勉強を終えた',
  problem_shown: '問題を出した', hint_given: 'ヒントを出した', hint_declined: 'ヒントを断られた', ask_unanswered: '返事がなかった',
  user_said: '言われた', user_solved_problem: '問題が解けた', user_missed_problem: '答えが違った',
  noticed_object: '見慣れない物を見た', asked_about_object: '物について聞いた', object_explained: '物について教わった',
  consent: '写真を送るかを決めてもらった',
};
var EPISODES_MAX = 200;

var Memory = {
  sessionOnly: [], // 長い記憶を切っているときの、このセッションだけの出来事

  enabled: function () { return Settings.get('memory', true); },
  episodes: function () { return (store.get('memory.episodes') || []).concat(Memory.sessionOnly); },

  remember: function (event, detail, source, confidence) {
    var e = { t: nowIso(), event: event, detail: clip(detail || '', 120), source: source || 'conversation', confidence: confidence == null ? 1 : confidence };
    if (event !== 'said') Report.event('memory', { event: event, text: (EVENT_JA[event] || event) + (e.detail ? ': ' + e.detail : ''), source: e.source }, e.confidence, e.source);
    if (!Memory.enabled()) {
      Memory.sessionOnly.push(e);
      if (Memory.sessionOnly.length > 100) Memory.sessionOnly = Memory.sessionOnly.slice(-100);
    } else {
      var list = store.get('memory.episodes') || [];
      list.push(e);
      if (list.length > EPISODES_MAX) list = list.slice(list.length - EPISODES_MAX);
      store.set('memory.episodes', list);
    }
    if (typeof Panel !== 'undefined') attempt('panel.memory', Panel.refreshMemory);
  },

  recent: function (n) {
    var list = Memory.episodes();
    return list.slice(Math.max(0, list.length - (n || 20)));
  },

  relation: function () {
    return (!Memory.enabled() && store.get('session.relation')) || store.get('relation.state') || { affinity: 0.3, mood: 0, activity: 0.5, hintDeclines: 0, sessions: 0, lastSessionEnd: null };
  },
  updateRelation: function (change) {
    var r = Memory.relation();
    for (var k in change) r[k] = change[k];
    r.affinity = Math.max(0, Math.min(1, r.affinity || 0));
    r.mood = Math.max(-1, Math.min(1, r.mood || 0));
    r.hintDeclines = Math.max(0, Math.min(20, r.hintDeclines || 0));
    if (Memory.enabled()) store.set('relation.state', r);
    else store.set('session.relation', r); // 残さない (persist に入っていない)
    return r;
  },

  // 物は「最後にどこで見たか」だけを覚える。今もそこにあるとは言わない (仕様 5.5)
  sawObject: function (name, where, confidence) {
    var objects = store.get('memory.objects') || {};
    objects[name] = { where: where, t: nowIso(), confidence: confidence };
    var keys = Object.keys(objects);
    if (keys.length > 60) { // 古いものから忘れる
      keys.sort(function (a, b) { return objects[a].t < objects[b].t ? -1 : 1; });
      keys.slice(0, keys.length - 60).forEach(function (k) { delete objects[k]; });
    }
    if (Memory.enabled()) store.set('memory.objects', objects);
  },
  lastSeen: function (name) {
    var objects = store.get('memory.objects') || {};
    if (objects[name]) return objects[name];
    // 「ハサミ」と「青いハサミ」のような言い方の違いは、含まれていれば同じとみなす
    var keys = Object.keys(objects).filter(function (k) { return k.indexOf(name) >= 0 || name.indexOf(k) >= 0; });
    return keys.length ? objects[keys[0]] : null;
  },

  // LLM に渡す「覚えていること」。時刻と出どころ付き。ここに無い出来事は語らせない
  forPrompt: function () {
    var lines = Memory.recent(20).map(function (e) {
      return '- ' + e.t + ' [' + e.source + ', ' + Math.round(e.confidence * 100) + '%] ' + (EVENT_JA[e.event] || e.event) + (e.detail ? ': ' + e.detail : '');
    });
    var objects = store.get('memory.objects') || {};
    var seen = Object.keys(objects).slice(0, 15).map(function (k) { return '- ' + k + ': 最後に見たのは ' + objects[k].where + ' (' + objects[k].t + ')'; });
    var r = Memory.relation();
    return '覚えている出来事 (これ以外は知らない):\n' + (lines.join('\n') || '- (まだ無い)') +
      '\n最後に見た物:\n' + (seen.join('\n') || '- (無い)') +
      '\n関係: 親密度 ' + r.affinity.toFixed(2) + ' / 機嫌 ' + r.mood.toFixed(2) + ' / ヒントを断られた回数 ' + r.hintDeclines;
  },

  // 設定パネルに出す「覚えていること」(新しい順。仕様 25: 見られる・消せる)
  view: function (n) {
    var list = Memory.episodes().filter(function (e) { return e.event !== 'said'; });
    var lines = list.slice(Math.max(0, list.length - (n || 7))).reverse().map(function (e) {
      // 設定パネルの 1 行 (38 px で全角 28 文字) に収める: 今日なら時刻だけ、別の日なら日付だけ、中身は 10 文字まで
      var d = new Date(e.t);
      var today = new Date().toDateString() === d.toDateString();
      var when = today ? ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2) : (d.getMonth() + 1) + '/' + d.getDate();
      var detail = e.detail ? '「' + clip(e.detail, 11) + '」' : '';
      return when + '  ' + (EVENT_JA[e.event] || e.event) + detail;
    });
    if (!Memory.enabled()) lines.unshift('(長い記憶は切っています。今回の分だけ)');
    return lines.join('\n') || 'まだ何も覚えていません';
  },

  // ---- 消す (仕様 11.4)。学習記録は PC の画面の「データ」で消す ----
  forget: function (what) {
    if (what === 'today') {
      var dayStart = new Date();
      dayStart.setHours(0, 0, 0, 0);
      store.set('memory.episodes', (store.get('memory.episodes') || []).filter(function (e) { return new Date(e.t).getTime() < dayStart.getTime(); }));
      Memory.sessionOnly = [];
    } else if (what === 'relation') {
      storage.forget('relation.');
    } else if (what === 'objects') {
      storage.forget('memory.objects');
      storage.forget('memory.interests');
      store.set('memory.episodes', (store.get('memory.episodes') || []).filter(function (e) {
        return ['noticed_object', 'asked_about_object', 'object_explained'].indexOf(e.event) < 0;
      }));
    } else if (what === 'seat') {
      Presence.forgetSeat();
    } else if (what === 'all') {
      storage.forget('memory.');
      storage.forget('learning.'); // 前の版が端末に残していた学習記録も消す
      storage.forget('relation.');
      Presence.forgetSeat();
      Memory.sessionOnly = [];
    }
    storage.save();
    Report.event('memory', { event: 'forgotten', text: '消した: ' + what }, 1, 'user_command');
    log('memory forgotten: ' + what);
    if (typeof Panel !== 'undefined') attempt('panel.memory', Panel.refreshMemory);
  },

  // 特定の物に関する記録だけを消す (仕様 11.4)。声: 「〇〇のこと忘れて」
  forgetObject: function (name) {
    var objects = store.get('memory.objects') || {};
    var hit = Object.keys(objects).filter(function (k) { return k.indexOf(name) >= 0 || name.indexOf(k) >= 0; });
    hit.forEach(function (k) { delete objects[k]; });
    store.set('memory.objects', objects);
    store.set('memory.interests', (store.get('memory.interests') || []).filter(function (i) { return hit.indexOf(i.name) < 0 && i.name.indexOf(name) < 0; }));
    store.set('memory.episodes', (store.get('memory.episodes') || []).filter(function (e) { return String(e.detail).indexOf(name) < 0; }));
    storage.save();
    Report.event('memory', { event: 'forgotten', text: '物の記録を消した: ' + name }, 1, 'user_command');
    return hit.length > 0;
  },
};

// ==== 声と会話 (仕様 CH-03 / 8.2 / 8.6 / 19.6) ====
// 聞く: quest-input のマイクが「話し終わった」ら WAV を PC の音声認識へ (同時に 1 本。待っているのは最後の 1 つだけ)。
// 話す: 読み上げの音声を、妹の位置から鳴らす (VRM なので口が声に合わせて動く)。字幕も出す。新しい言葉が来たら前の声は止める。
// 勉強の中身 (ヒント・答え合わせ) は「PC の先生」がする。ここは、それ以外のおしゃべり。
// PC に届かないときは字幕だけで話し、「PC とつながってない」は 1 分に 1 回まで言う。
var PERSONA =
  'あなたはユーザーの妹のキャラクター。現実の部屋の中に MR で表示されている。短く、自然な話し言葉で、1〜2 文で答える。\n' +
  '守ること: 下の「覚えている出来事」と、今渡された観測に無いことを、見た・知っているように言わない。' +
  'ユーザーがヘッドセットを外していた間のことは分からない。物の場所は「最後に見たのは〜」と時刻付きで言い、今もあるとは言わない。' +
  '感情は演出であり、本当に感じているとは言わない。勉強中は答えそのものを言わない。\n' +
  '話し方: 兄に話す妹のタメ口 (です・ます は使わない)。声で読み上げるので、数式の記号 ($ や \\) ・かっこのト書き・「」で囲んだ台詞は書かない。';

// LLM の返事を、声で読める短い台詞に整える (ローカルの小さなモデルは指示を守りきれないため)
function cleanReply(text) {
  if (!text) return null;
  var t = String(text).replace(/<think>[\s\S]*?<\/think>/g, '').replace(/\$|\\[a-z]+|\\/g, '').replace(/（[^）]*）/g, '').replace(/\([^)]*[ぁ-んァ-ヶ一-龠][^)]*\)/g, '').replace(/\n+/g, ' ').trim();
  t = t.replace(/^「(.*)」$/, '$1').trim();
  var sentences = t.match(/[^。！？!?]+[。！？!?]?/g) || [];
  t = sentences.slice(0, 2).join('').trim();
  return t || null;
}

// PC の Say の表情 → VRM の表情
var EXPRESSION_VRM = { happy: 'happy', surprised: 'surprised', worried: 'sad', thinking: 'relaxed' };

var Voice = {
  speaking: false,
  quiet: false,   // 「静かにして」で true (仕様 19.6: 自発発話を止められる)
  lineId: 0,
  handle: null,
  wantAudio: null, // 読み上げの通信がふさがっている間に来た言葉 (最後の 1 つだけ)
  offlineSaidAt: 0,
  recentLines: [], // 最近の妹の言葉 (スピーカーの声を拾ったか見分ける)

  // what: 文字か、PC の Say ({ text, expression?, audio? })
  say: function (what, done) {
    var text = typeof what === 'string' ? what : (what && what.text);
    if (!text) { if (done) attempt('say.done', done); return; }
    text = clip(String(text), 220);
    var audioPath = what && typeof what === 'object' ? what.audio : null;
    var expression = what && typeof what === 'object' ? EXPRESSION_VRM[what.expression] : null;
    // 前の声を止める (重ねて話さない)
    if (Voice.handle && HAS.audio) { var h = Voice.handle; Voice.handle = null; attempt('audio.stop', function () { audio.stop(h); }); }
    var id = ++Voice.lineId;
    store.set('talk.line', text);
    ui.setVisibility('subtitlePlate', true);
    Memory.remember('said', text, 'self');
    Voice.recentLines.push(text);
    if (Voice.recentLines.length > 4) Voice.recentLines = Voice.recentLines.slice(-4);
    Report.event('action', { what: 'say', text: text, by: audioPath ? 'pc_teacher' : 'quest' });
    Voice.speaking = true;
    if (expression && sisterHere()) attempt('expression', function () { vrm.setExpression(CONFIG.character, expression, 60); });
    var finished = false;
    var finish = function () {
      if (finished) return;
      finished = true;
      if (Voice.lineId === id) {
        Voice.speaking = false;
        if (expression && sisterHere()) attempt('expression', function () { vrm.setExpression(CONFIG.character, expression, 0); });
        later('subtitle', 2500, function () {
          if (Voice.lineId !== id) return; // 次の言葉が出ている
          store.set('talk.line', '');
          ui.setVisibility('subtitlePlate', false);
        });
      }
      if (done) attempt('say.done', done);
    };
    var readSeconds = Math.min(10, 1.2 + text.length / 7); // 声が出せないときは、読む時間だけ「話している」
    // 終わりの知らせが来なくても「話している」のままにしない (残ると自分から話さず・ヒントも聞かなくなる)
    later('say.watchdog', (readSeconds + 20) * 1000, function () {
      if (!finished && Voice.lineId === id && Voice.handle && HAS.audio) { var hh = Voice.handle; Voice.handle = null; attempt('audio.stop', function () { audio.stop(hh); }); }
      finish();
    });
    if (!PC.online || !HAS.audio) { later('say.read', readSeconds * 1000, finish); return; }
    Voice.fetchAudio(id, text, audioPath, finish, readSeconds);
  },

  fetchAudio: function (id, text, audioPath, finish, readSeconds) {
    var opts = audioPath
      ? { url: /^https?:\/\//.test(audioPath) ? audioPath : url(audioPath), method: 'GET', responseType: 'base64', timeout: 15 }
      : { url: url('/v1/audio/speech'), method: 'POST', json: { model: CONFIG.ttsModel, voice: CONFIG.ttsVoice, input: text, response_format: 'wav' }, responseType: 'base64', timeout: 15 };
    var started = Net.call('tts', opts, function (r) {
      // 待たせていた言葉があれば、それを取りに行く
      var waiting = Voice.wantAudio;
      Voice.wantAudio = null;
      if (waiting && waiting.id === Voice.lineId) Voice.fetchAudio(waiting.id, waiting.text, waiting.audioPath, waiting.finish, waiting.readSeconds);
      if (id !== Voice.lineId) { finish(); return; } // もう次の言葉が出ている: 古い声は鳴らさない
      if (!r.ok || !r.base64) { // 声が出せなくても字幕は出ている (仕様 8.6)
        if (r.status !== 204) log('tts failed: ' + (r.error || r.status));
        later('say.read', readSeconds * 1000, finish);
        return;
      }
      var opts2 = sisterHere() ? { at: CONFIG.character } : {};
      Voice.handle = audio.play(r.base64, opts2, function () { finish(); });
    });
    if (!started) Voice.wantAudio = { id: id, text: text, audioPath: audioPath, finish: finish, readSeconds: readSeconds };
  },

  // 自分から話しかけるとき (静音中・話している最中・ユーザーが話している最中は言わない)
  offer: function (what) {
    if (Voice.quiet || Voice.speaking || store.get('mic.speaking')) return false;
    Voice.say(what);
    return true;
  },

  // PC に届かない・LLM が答えない: 短く 1 回だけ言う (毎回は言わない)
  unreachable: function (r) {
    if (r && r.error === 'superseded') return;
    Stage.fail(r || { error: 'offline' });
    if (Date.now() - Voice.offlineSaidAt < 60000) return;
    Voice.offlineSaidAt = Date.now();
    if (!PC.online) Voice.say('ごめん、今 PC とつながってないの。つながったら手伝うね');
    else if (r && r.status === 429) Voice.say('ちょっと考えすぎちゃった。少ししてからもう一回言って');
    else Voice.say('ごめん、今うまく考えられないみたい');
  },

  chat: function (userText, extra, done) {
    var messages = [
      { role: 'system', content: PERSONA + '\n\n' + Memory.forPrompt() + (extra ? '\n\n今の状況: ' + extra : '') },
      { role: 'user', content: userText },
    ];
    Llm.run('chat', { url: url('/v1/chat/completions'), method: 'POST', json: { model: CONFIG.chatModel, messages: messages, max_tokens: 200 }, responseType: 'json', timeout: 40 },
      function (r) { done(cleanReply(replyText(r)), r); }, true);
  },

  setQuiet: function (on) {
    Voice.quiet = on;
    Settings.set('quiet', on);
  },
};
Voice.quiet = Settings.get('quiet', false);

// ---- 聞く ----
var Ears = {
  pending: null,
  heardCount: 0,
  hear: function (wav) {
    if (!PC.online) { Voice.unreachable(null); return; }
    var started = Net.call('stt', {
      url: url('/v1/audio/transcriptions'), method: 'POST',
      form: { model: CONFIG.sttModel, language: 'ja', file: { base64: wav, filename: 'speech.wav', type: 'audio/wav' } },
      responseType: 'json', timeout: 20,
    }, function (r) {
      var text = r.ok && r.json ? String(r.json.text || '').trim().replace(/^[\s。、.]+$/, '') : '';
      if (!r.ok) log('stt failed: ' + (r.error || r.status));
      if (text && Ears.isEcho(text)) { log('stt: heard my own voice; ignored: ' + text); Stage.sttEnd('', null); Stage.heard.text = '(妹の声を拾ったので無視)'; text = ''; }
      else Stage.sttEnd(text, r);
      if (text) {
        Ears.heardCount += 1;
        Memory.remember('user_said', text, 'microphone_asr', 0.9);
        Report.event('observation', { what: 'speech', text: '聞こえた: 「' + text + '」' }, 0.9, 'microphone');
        attempt('onUserSaid', function () { onUserSaid(text); });
      }
      var next = Ears.pending;
      Ears.pending = null;
      if (next) Ears.hear(next);
    });
    if (!started) Ears.pending = wav; // 前の言葉を文字にしている間は、最後の 1 つだけ待たせる
    else Stage.sttBegin();
  },
  // 妹の声 (スピーカー) を拾っただけか: 最近の妹の言葉に、聞こえた文字の 6 文字以上がそのまま入っている
  isEcho: function (text) {
    var t = String(text).replace(/[\s、。！？!?,.]/g, '');
    if (t.length < 4) return false;
    return Voice.recentLines.some(function (line) {
      var l = String(line).replace(/[\s、。！？!?,.]/g, '');
      if (l.indexOf(t) >= 0) return true;
      for (var i = 0; i + 6 <= t.length; i += 3) if (l.indexOf(t.slice(i, i + 6)) >= 0) return true;
      return false;
    });
  },
};

var Mic = {
  wanted: function () { return HAS.mic && Settings.get('mic', true) && PC.wearing; },
  lastSpeechEndAt: 0,
  crossed: false,        // 前の発話のあとで、音量が「話し始め」を超えたことがあるか
  quietSince: Date.now(),
  warned: false,
  nextWatchAt: 0,
  apply: function () {
    if (!HAS.mic) return;
    attempt('mic.apply', function () { if (Mic.wanted()) mic.start(); else mic.stop(); });
    Mic.quietSince = Date.now();
    Mic.crossed = false;
    Stage.render();
  },
  // 毎秒: 開いているはずなのに閉じていれば開き直す (起動直後は拡張機能の準備がまだのことがある)。
  // 勉強中に 60 秒、声が 1 度も「話し始め」の音量に届かなければ、1 回だけ知らせる
  watch: function () {
    if (!HAS.mic) return;
    var st = Stage.micStatus();
    if (Mic.wanted() && (st === 'off' || st === 'failed') && Date.now() >= Mic.nextWatchAt) {
      Mic.nextWatchAt = Date.now() + 5000;
      attempt('mic.restart', function () { mic.start(); });
    }
    if (st === 'denied' && !Mic.toldDenied) { Mic.toldDenied = true; Hud.notice('マイクが許可されていません (Quest の設定 → アプリ → 権限 → マイク)', 20); }
    if (st !== 'on' || !Mic.wanted()) { Mic.quietSince = Date.now(); return; }
    if (Mic.level() >= Mic.threshold) Mic.crossed = true;
    if (Mic.crossed) { Mic.quietSince = Date.now(); Mic.crossed = false; return; }
    if (!Mic.warned && Study.mode === 'study' && Date.now() - Math.max(Mic.quietSince, Mic.lastSpeechEndAt) > 60000) {
      Mic.warned = true;
      Hud.notice('声が届いていないかも (マイクの許可・音量)', 15);
      log('mic: no voice above threshold for 60 s while studying');
    }
  },
  threshold: 0.35, // quest-input の voiceThreshold と同じ値
  level: function () { return Stage.micLevel(); },
};

if (HAS.mic) {
  mic.on('speechEnd', safe('mic.speechEnd', function (r) {
    Mic.lastSpeechEndAt = Date.now();
    Stage.render();
    if (!Settings.get('mic', true)) return;
    if (!r || !r.ok || !r.wav || r.seconds < 0.4) return;
    // 妹が話している間の声も文字にする (割り込みを捨てない)。妹の声を拾っただけなら、文字にしたあとで捨てる
    Ears.hear(r.wav);
  }));
  mic.on('speechStart', safe('mic.speechStart', function () { Mic.crossed = true; Stage.render(); }));
}

// 言われたことの振り分け。操作・同意・勉強・記憶の操作が先、それ以外は会話
function onUserSaid(text) {
  if (Consent.onSpeech(text)) return;
  if (/静かに|黙って/.test(text)) { Voice.setQuiet(true); Voice.say('うん、静かにしてるね'); return; }
  if (/話していい|しゃべっていい|喋っていい/.test(text)) { Voice.setQuiet(false); Voice.say('やった'); return; }
  if (/^設定|設定(を)?(開|ひら|見せ)/.test(text)) { Panel.show(); return; }
  var forget = /(.+?)のこと(は)?(を)?(忘れて|わすれて)/.exec(text);
  if (forget) {
    var name = forget[1].replace(/^(あの|その|この)/, '');
    Voice.say(Memory.forgetObject(name) ? name + 'のこと、忘れたよ' : name + 'のことは、もともと覚えてなかったよ');
    return;
  }
  if (Study.onSpeech(text)) return;
  if (Curiosity.onSpeech(text)) return;
  var where = /(.+?)(って|は|が)?(どこ|どこにある)/.exec(text);
  if (where) {
    var seen = Memory.lastSeen(where[1].replace(/[はがの]$/, ''));
    if (seen) { Voice.say('最後に見たのは' + seen.where + 'だよ。今もあるかは分かんないけど'); return; }
  }
  // 勉強中の質問は PC の先生へ (タブレットと同じ先生が答える)
  if (Study.mode === 'study' && Teacher.problem && /[?？]|かな$|の$|って何|ってなに|どう|なんで|どうして|教えて|わから|分から/.test(text)) {
    Teacher.ask('hint', text, true);
    return;
  }
  if (!PC.online) { Voice.unreachable(null); return; }
  Voice.chat(text, Study.describe(), function (reply, r) {
    if (reply) {
      Voice.say(reply);
      Memory.updateRelation({ affinity: Memory.relation().affinity + 0.005 });
    } else Voice.unreachable(r);
  });
}

// ==== PC の先生 (Cohabit PC の /tablet/api/*。タブレットと同じ先生・同じ今の問題・同じ学習記録) ====
// 教科は決めない。問題を作る・ノートを読む・正誤・ヒント・説明は、すべて PC の LLM がする (Quest は式を計算しない)。
// タブレットで始めた問題は、Quest をかぶってもそのまま続く (/tablet/api/session を 5 秒ごとに見る)。
// どの返事も、送ったときと問題が変わっていたら捨てる。PC に届かなければ、妹が 1 回だけ短く言って、勉強はそのまま続ける。

// ---- 机の「今見ているところ」と、その写真 ----
var Desk = {
  capturing: false,
  lookingDown: function () {
    var p = viewer.pose();
    return !!p && p.tracking !== false && !!p.forward && p.forward.y < -0.35;
  },
  // 見ている先が机ならその点。見ていなければ null (机全体を見られる前提にしない: 仕様 5.3)
  gazePoint: function () {
    if (!HAS.room || !Desk.lookingDown()) return null;
    var hit = room.lookAt('table');
    if (!hit || !hit.hit) hit = room.lookAt('any'); // 机として登録されていない台でも、下を向いて見ている面なら使う
    return hit && hit.hit && (!hit.normal || hit.normal.y > 0.7) ? { x: hit.x, y: hit.y, z: hit.z } : null;
  },
  // 見ている机の 50 cm 四方を撮る → fn('data:image/jpeg;base64,…' か null)。同意が無ければ撮らない (仕様 8.2 / 25)
  photo: function (fn) {
    if (Desk.capturing || !HAS.camera || !attempt('camera.available', function () { return camera.available(); })) { fn(null); return; }
    if (!Consent.imagesAllowed()) { fn(null); return; }
    var point = Desk.gazePoint();
    if (!point) { fn(null); return; }
    Desk.capturing = true;
    store.set('cohabit.sending', '● 見ている机の 50cm 四方を PC へ送っています (保存しません)'); // 何を送っているかを見せる (仕様 25)
    var done = false;
    var finish = function (image) {
      if (done) return;
      done = true;
      Desk.capturing = false;
      if (!image) store.set('cohabit.sending', '');
      attempt('desk.photo', function () { fn(image); });
    };
    var watchdog = later('desk.watchdog', 12000, function () { finish(null); });
    try {
      camera.capture({ maxWidth: 1024, quality: 80, around: { x: point.x, y: point.y, z: point.z, size: 0.5 } }, function (shot) {
        clearTimeout(watchdog);
        if (!shot || !shot.ok || !shot.image) { log('capture failed: ' + (shot && shot.error)); finish(null); return; }
        finish('data:image/jpeg;base64,' + shot.image);
      });
    } catch (e) { clearTimeout(watchdog); finish(null); }
  },
  sent: function () { store.set('cohabit.sending', ''); },
};

var Teacher = {
  problem: null,     // { id, subject, text, goal }
  solved: false,
  gen: 0,            // 問題が変わるたびに増える (古い返事を捨てる)
  solvedCount: 0,    // この勉強で解けた数 (終わりのひとこと用。記録は PC)
  nextSyncAt: 0,
  autoNextTimer: null,

  // ---- 問題 ----
  setProblem: function (p, how) {
    if (!p || !p.id) return false;
    if (Teacher.problem && Teacher.problem.id === p.id) return false;
    Teacher.problem = { id: String(p.id), subject: String(p.subject || ''), text: String(p.text || ''), goal: String(p.goal || '') };
    Teacher.solved = false;
    Teacher.gen += 1;
    if (Teacher.autoNextTimer) { clearTimeout(Teacher.autoNextTimer); Teacher.autoNextTimer = null; }
    Teacher.stopChoosing(); // タブレット等から問題が来たら、選ぶのは終わり
    if (Study.mode !== 'idle') Board.show(Teacher.problem); // 勉強していないときは、始めたときに出す
    Study.onNewProblem();
    Memory.remember('problem_shown', (Teacher.problem.subject ? Teacher.problem.subject + ': ' : '') + Teacher.problem.text, how || 'pc_teacher');
    Report.event('action', { what: 'quiz', text: '問題を出した (' + (how || 'pc_teacher') + '): ' + clip(Teacher.problem.text, 80) });
    return true;
  },
  clearProblem: function () {
    Teacher.problem = null;
    Teacher.solved = false;
    Teacher.gen += 1;
    if (!Teacher.choosing) Board.hide(); // 何をやるか聞いている板は残す
  },

  // ---- 何をやるかを選ぶ (問題は勝手に決めない。ユーザーが言ったものだけ) ----
  // choosing: null | 'continue' (PC にある問題を続けるか聞いた) | 'topic' (何をやるか聞いた) | 'waiting' (頼んだ問題を待っている)
  choosing: null,
  chooseTimer: null,
  stopChoosing: function () {
    Teacher.choosing = null;
    if (Teacher.chooseTimer) { clearTimeout(Teacher.chooseTimer); Teacher.chooseTimer = null; }
  },
  micHint: function () {
    if (!HAS.mic || !Settings.get('mic', true)) return 'マイクが止まっています。設定 (左手メニュー) でマイクを入れて、声で教えてね';
    if (!PC.online) return 'PC につながると、声で選べます';
    return '例: 英語の現在完了 / 数学の二次関数 / 苦手なの / おまかせ';
  },
  offerContinue: function () {
    if (!Teacher.problem) { Teacher.askTopic(); return; }
    Teacher.stopChoosing();
    Teacher.choosing = 'continue';
    var short = clip(Teacher.problem.text, 18);
    Voice.say('さっきの『' + short + '』の続き、やる？');
    Board.prompt('続き、やる？', Teacher.problem.text, '「うん」で続き / 「別の」で選び直す');
    Teacher.chooseTimer = later('choose.timeout', 20000, function () {
      Teacher.chooseTimer = null;
      if (Teacher.choosing === 'continue' && Study.mode === 'study') Teacher.askTopic();
    });
  },
  askTopic: function (silent) {
    Teacher.stopChoosing();
    Teacher.choosing = 'topic';
    if (!silent) Voice.say('今日は何やる？ 教科とか単元を言って');
    Board.prompt('今日は何やる？', '教科や単元を声で言ってね', Teacher.micHint());
  },
  continueProblem: function () {
    Teacher.stopChoosing();
    Board.hide();
    Board.show(Teacher.problem);
    Voice.say('じゃあ続きね');
  },
  // 選んでいる間に言われたこと。使ったら true
  choose: function (text) {
    var c = Teacher.choosing;
    if (!c || c === 'waiting') return false;
    if (c === 'continue') {
      if (/別|ほか|他|違う|ちがう|ううん|いや|やらない|いい$|いいや/.test(text)) { Teacher.askTopic(); return true; }
      if (/^(うん|はい|やる|お願い|いいよ|そう|おっけー|OK)|続き/i.test(text)) { Teacher.continueProblem(); return true; }
      // 続けるとも別とも言わずに、やりたいことを言った: それを選んだことにする
    }
    if (Teacher.problem && !Teacher.solved && /さっき|続き/.test(text)) { Teacher.continueProblem(); return true; }
    if (/苦手|おまかせ|お任せ|まかせる|任せる/.test(text)) { Teacher.newProblem('weak'); return true; }
    var topic = String(text).replace(/^(えっと|えーと|うーん|じゃあ|今日は|きょうは)[、,\s]*/g, '')
      .replace(/(の問題)?(を|が|で)?(やる|やりたい|勉強する|勉強したい|にする|がいい|お願い|おねがい|出して|ちょうだい|ください|かな|で)?[。!！?？\s]*$/, '').trim();
    if (topic.length < 2) { Voice.say('ごめん、もう一回。教科か単元を言って'); return true; }
    Teacher.newProblem('topic', { topic: clip(topic, 60) });
    return true;
  },

  // from: next | weak | topic | text。level: easier | same | harder
  newProblem: function (from, extra) {
    if (!PC.online) { Voice.unreachable(null); return; }
    var wasChoosing = Teacher.choosing;
    if (wasChoosing) Teacher.choosing = 'waiting';
    var body = { from: from };
    if (extra && extra.topic) body.topic = extra.topic;
    if (extra && extra.level) body.level = extra.level;
    if (extra && extra.text) body.text = extra.text;
    var gen = Teacher.gen;
    Board.waiting('問題を考えています…');
    Llm.run('problem', { url: url('/tablet/api/problem'), method: 'POST', json: body, responseType: 'json', timeout: 45 }, function (r) {
      Board.waiting(null);
      if (Teacher.choosing === 'waiting') Teacher.choosing = 'topic'; // うまくいかなければ、聞いたまま次の言葉を待つ
      if (r.status === 409 && from === 'weak') { // まだ記録が無い: 何をやるかを聞く (勝手に決めない)
        Voice.say('まだ記録が無いから、何をやるか教えて');
        if (Study.mode === 'study') Teacher.askTopic(true);
        return;
      }
      if (r.status === 409) { if (Study.mode === 'study') Teacher.askTopic(); return; } // 前の問題が無い → 何をやるか聞く
      if (!r.ok || !r.json || !r.json.problem || !r.json.problem.id) {
        Teacher.failed(r, 'problem');
        if (wasChoosing && Study.mode === 'study') Board.prompt('今日は何やる？', '教科や単元を声で言ってね', Teacher.micHint());
        return;
      }
      var same = Teacher.problem && Teacher.problem.id === String(r.json.problem.id);
      if (!same && gen !== Teacher.gen && Teacher.problem) return; // その間に別の問題が来た (タブレットから等)
      if (!same) Teacher.setProblem(r.json.problem, 'pc_teacher');
      if (r.json.say) Voice.say(r.json.say);
    }, true);
  },

  // ---- ヒント / 説明 / 答え (level: hint | explain | answer)。withPhoto なら見ている机も見せる ----
  ask: function (level, question, withPhoto) {
    if (!PC.online) { Voice.unreachable(null); return; }
    if (!Teacher.problem && !question) {
      Voice.say('どの問題か分かんないや。「問題出して」って言ってくれたら出すよ');
      return;
    }
    var gen = Teacher.gen;
    var send = function (page) {
      if (gen !== Teacher.gen) { Desk.sent(); return; }
      var body = { level: level };
      if (Teacher.problem) body.problemId = Teacher.problem.id;
      if (question) body.question = clip(question, 300);
      if (page) body.page = page;
      Llm.run('ask', { url: url('/tablet/api/ask'), method: 'POST', json: body, responseType: 'json', timeout: 45 }, function (r) {
        Desk.sent();
        if (gen !== Teacher.gen) return;
        if (r.status === 409) { Teacher.lostProblem(); return; }
        if (!r.ok || !r.json || !r.json.say) { Teacher.failed(r, 'ask'); return; }
        Voice.say(r.json.say);
        if (level === 'hint') {
          Memory.remember('hint_given', Teacher.problem ? clip(Teacher.problem.text, 40) : clip(question, 40), 'pc_teacher');
          Presence.pointAt(Desk.gazePoint());
        }
        Report.event('action', { what: 'hint', text: level + ': ' + r.json.say.text });
      }, true);
    };
    if (withPhoto) Desk.photo(send); else send(null);
  },

  // ---- 声の答え (「答えは …」の後ろ) ----
  answer: function (said) {
    if (!Teacher.problem) return false;
    if (!PC.online) { Voice.unreachable(null); return true; }
    var gen = Teacher.gen;
    Llm.run('answer', { url: url('/tablet/api/answer'), method: 'POST', json: { problemId: Teacher.problem.id, answer: clip(said, 200), from: 'quest' }, responseType: 'json', timeout: 45 }, function (r) {
      if (gen !== Teacher.gen) return;
      if (r.status === 409) { Teacher.lostProblem(); return; }
      if (!r.ok || !r.json) { Teacher.failed(r, 'answer'); return; }
      if (r.json.say) Voice.say(r.json.say);
      if (r.json.solved || r.json.correct === true) Teacher.onSolved('speech');
      else if (r.json.correct === false) {
        Board.footer('もう一回 — 「ヒント」でも');
        Memory.remember('user_missed_problem', clip(Teacher.problem.text, 40), 'pc_teacher', 0.9);
      }
    }, true);
    return true;
  },

  // ---- ノートを見て、間違い・迷いを見る (trigger: pause = 手が止まった / request = 「見て」) ----
  check: function (trigger) {
    if (!Teacher.problem || !PC.online) { if (trigger === 'request') Teacher.ask('hint', 'ノートを見て', true); return; }
    if (trigger === 'pause' && !Llm.idle()) return; // 裏の見守りは、ほかの用事があるときはしない
    var gen = Teacher.gen;
    Desk.photo(function (page) {
      if (!page) {
        if (trigger === 'request') Voice.say(Consent.imagesAllowed() ? 'ノートの方を見ててくれたら、見るよ' : '写真を送らない設定だから、ノートは見られないんだ');
        return;
      }
      if (gen !== Teacher.gen || (trigger === 'pause' && Study.mode !== 'study')) { Desk.sent(); return; }
      var t0 = Date.now();
      var started = Llm.run('check', { url: url('/tablet/api/check'), method: 'POST', json: { problemId: Teacher.problem.id, trigger: trigger, page: page, source: 'quest' }, responseType: 'json', timeout: 45 }, function (r) {
        Desk.sent();
        if (trigger === 'pause') { Study.lastCheckSeconds = (Date.now() - t0) / 1000; Study.lastCheckEndAt = Date.now(); }
        if (gen !== Teacher.gen) return;
        if (r.status === 409) { Teacher.lostProblem(); return; }
        if (!r.ok || !r.json) { if (trigger === 'request') Teacher.failed(r, 'check'); else log('check failed: ' + (r.error || r.status)); return; }
        Study.pcStuck = !!r.json.stuck;
        Report.event('observation', { what: 'notebook', trigger: trigger, solved: !!r.json.solved, stuck: !!r.json.stuck, said: r.json.say ? r.json.say.text : null }, null, 'quest_rgb');
        if (r.json.say) {
          if (trigger === 'request') Voice.say(r.json.say);
          else if (Voice.offer(r.json.say)) Study.lastIntervention = nowIso();
        } else if (trigger === 'request') Voice.say('うん、そのまま続けて');
        if (r.json.solved) Teacher.onSolved('notebook');
      }, trigger === 'request');
      if (!started) Desk.sent();
    });
  },

  onSolved: function (how) {
    if (Teacher.solved || !Teacher.problem) return;
    Teacher.solved = true;
    Teacher.solvedCount += 1;
    Board.footer('正解！');
    Memory.remember('user_solved_problem', clip(Teacher.problem.text, 40), how === 'speech' ? 'pc_teacher_speech' : 'pc_teacher_notebook', 0.9);
    Memory.updateRelation({ affinity: Memory.relation().affinity + 0.01, mood: Memory.relation().mood + 0.1 });
    if (sisterHere()) {
      attempt('happy', function () { vrm.setExpression(CONFIG.character, 'happy', 80); });
      later('happy.off', 2500, function () { if (sisterHere()) vrm.setExpression(CONFIG.character, 'happy', 0); });
    }
    // 勉強中なら、少ししたら同じ単元の次の問題 ("next": PC が前の結果から難しさを決める)。「終わり」と言えば止まる
    if (Settings.get('autoNext', true)) {
      var gen = Teacher.gen;
      Teacher.autoNextTimer = later('autoNext', 9000, function () {
        Teacher.autoNextTimer = null;
        if (gen === Teacher.gen && Teacher.solved && Study.mode === 'study') Teacher.newProblem('next');
      });
    }
  },

  // PC が「その問題は今の問題じゃない」と言った (PC が起動し直した・タブレットで別の問題にした)
  lostProblem: function () {
    Teacher.nextSyncAt = 0;
    Teacher.sync(function (hadProblem) {
      if (hadProblem) return;
      if (Study.mode === 'study') Teacher.askTopic(); // 勉強中なら、何をやるか聞き直す
      else Voice.say('PC の方で問題が変わったみたい');
    });
  },

  failed: function (r, what) {
    log('teacher ' + what + ' failed: ' + (r && (r.error || r.status)));
    Voice.unreachable(r);
  },

  // ---- 今の問題を PC と合わせる (タブレット・PC の画面で出した問題も、ここで届く) ----
  sync: function (done) {
    if (!PC.online) { if (done) done(!!Teacher.problem); return; }
    var gen = Teacher.gen;
    var started = Net.call('session', { url: url('/tablet/api/session'), method: 'GET', responseType: 'json', timeout: 4 }, function (r) {
      if (!r.ok || !r.json) { if (done) done(!!Teacher.problem); return; }
      Teacher.weak = r.json.weak && r.json.weak.summary ? String(r.json.weak.summary) : null;
      var p = r.json.problem;
      if (Llm.busy === 'problem') { if (done) done(!!Teacher.problem); return; } // 頼んだ問題の返事を待っている: そちらで受ける
      if (p && p.id && gen === Teacher.gen) {
        if (Teacher.setProblem(p, 'pc_session') && Study.mode === 'study') Voice.offer('問題、こっちにも出しておくね');
        if (r.json.solved && !Teacher.solved && Teacher.problem && Teacher.problem.id === p.id) { Teacher.solved = true; Board.footer('正解！'); }
      } else if (!p && Teacher.problem && gen === Teacher.gen) {
        Teacher.clearProblem(); // PC にもう問題が無い (起動し直した・消した)
        if (Study.mode === 'study' && !done && !Teacher.choosing) Teacher.askTopic();
      }
      if (done) done(!!Teacher.problem);
    });
    if (!started && done) done(!!Teacher.problem);
  },

  // 毎秒から: 勉強中は 5 秒ごと、それ以外は 30 秒ごと
  tick: function () {
    if (!PC.online || Date.now() < Teacher.nextSyncAt) return;
    Teacher.nextSyncAt = Date.now() + (Study.mode === 'study' ? 5000 : 30000);
    Teacher.sync();
  },
};

// PC が (また) 見つかった: すぐ今の問題を合わせる。勉強中で問題が無ければ、何をやるか聞く
PC.onOnline(function () {
  Teacher.nextSyncAt = Date.now() + 5000;
  Teacher.sync(function (has) {
    if (Study.mode !== 'study' || Teacher.choosing) return;
    if (has && !Teacher.solved) Teacher.offerContinue(); else if (!has) Teacher.askTopic();
  });
});

// ==== 一緒に勉強する (仕様 3.3 / 5.3 / 5.4 / 6.1〜6.4) ====
// 観測できたことだけで判断する。手が見えないときは「不明」にして口を出さない。
// 手 (ペン先の代わりに右手の人差し指) が書く動きのあとで止まったら、見ている机の 50cm 四方だけを撮って PC の先生に見せる。
// 話しかけるかどうかは、決まりで絞った候補 (黙る / 見る / 聞く / ヒント / 励ます) の順位を Lev に任せる。
// 断られるほど待つ時間が延びる。中身 (ヒント・間違い・正誤) は PC の先生が決める。

var CANDIDATES_STUDY = ['SILENT', 'OBSERVE', 'ASK', 'HINT', 'ENCOURAGE'];

var Study = {
  mode: 'idle',          // idle | study | break
  pausedBy: null,        // 'break' | 'headset_off'
  startedAt: null,
  lastProgressAt: null,  // 最後に書いていた時刻
  stillSeconds: 0,       // 手が止まっている秒数
  writing: false,
  writtenSinceCheck: 0,  // 前にノートを見てから、書いていた秒数
  handsKnown: false,
  lastHand: null,
  lastCheckAt: 0,
  lastIntervention: null,
  awaitingHintReply: null, // 「ヒントいる？」と聞いた時刻
  pcStuck: false,          // PC の先生の見立て (/check の stuck)
  decisionPending: false,
  nextDecisionAt: 0,

  set: function (mode) {
    Study.mode = mode;
    Study.hud();
  },

  // 左上の表示: 「● 勉強中 12:34  数学」
  hud: function () {
    var text;
    if (Study.mode === 'study' && Study.startedAt) {
      var s = Math.floor(secondsSince(Study.startedAt));
      text = '● 勉強中  ' + Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2) + (Teacher.problem && Teacher.problem.subject ? '  ' + clip(Teacher.problem.subject, 8) : '');
    } else if (Study.mode === 'break') text = '休憩中 (A で再開)';
    else text = 'A で勉強を始める';
    store.set('study.state', text);
  },

  start: function () {
    if (Study.mode === 'study') return;
    var resumed = Study.mode === 'break';
    if (!resumed) { Study.startedAt = nowIso(); Teacher.solvedCount = 0; }
    Study.set('study');
    Study.pausedBy = null;
    Study.stillSeconds = 0;
    Study.writtenSinceCheck = 0;
    Study.lastProgressAt = nowIso();
    Study.nextDecisionAt = Date.now() + 20000;
    Memory.remember('study_started', resumed ? '休憩のあと' : '', 'user_command');
    Report.event('session', { what: 'study_start', text: resumed ? '勉強を再開' : '勉強を始めた' });
    Presence.stopPlay();
    Presence.sitBeside();
    if (Settings.get('consent.images', null) === null && Settings.get('camera', true)) later('consent.ask', 4000, function () { Consent.ask(); });
    // 問題は勝手に決めない: PC に今の問題があれば続けるか聞き、無ければ何をやるか聞く (タイマーと妹はもう始まっている)
    Teacher.sync(function (has) {
      if (Study.mode !== 'study') return;
      if (resumed && has && !Teacher.solved) { Teacher.continueProblem(); return; }
      if (has && !Teacher.solved) Teacher.offerContinue();
      else if (PC.online) Teacher.askTopic();
      else {
        Voice.say('うん、隣にいるね。PC につながったら、何やるか聞くね');
        Board.prompt('今日は何やる？', 'PC につながったら、声で教えてね', Teacher.micHint());
      }
    });
  },

  pause: function (why) {
    if (Study.mode !== 'study') return;
    Study.pausedBy = why;
    Memory.remember('study_paused', why, why === 'headset_off' ? 'headset_sensor' : 'user_command');
    Report.event('session', { what: 'study_pause', text: why === 'headset_off' ? 'ヘッドセットが外されたので中断' : '休憩' });
    Study.awaitingHintReply = null;
    Teacher.stopChoosing();
    Study.set('break');
    if (why !== 'headset_off') Voice.say('うん、休憩しよ。続けるときは A か「続きやる」');
  },

  end: function () {
    if (Study.mode === 'idle') return;
    var n = Teacher.solvedCount;
    Memory.remember('study_ended', n ? n + ' 問解けた' : '', 'app');
    Report.event('session', { what: 'study_end', text: '勉強を終えた (この勉強で解けた問題 ' + n + ')' });
    Study.set('idle');
    Study.pausedBy = null;
    Study.awaitingHintReply = null;
    if (Teacher.autoNextTimer) { clearTimeout(Teacher.autoNextTimer); Teacher.autoNextTimer = null; }
    Teacher.stopChoosing();
    Board.hide(); // 問題は PC に残る (次に始めたとき・タブレットで続けられる)
    Voice.say(n > 0 ? 'おつかれ。今日は ' + n + ' 問解けたね' : 'おつかれさま');
    if (sisterHere()) attempt('stopAnimation', function () { vrm.stopAnimation(CONFIG.character); }); // 力を抜いて立つ
    storage.save();
  },

  describe: function () {
    if (Study.mode === 'idle') return '勉強はしていない';
    return (Study.mode === 'study' ? '勉強中' : '休憩中') + (Teacher.problem ? '。今の問題: ' + clip(Teacher.problem.text, 80) : '');
  },

  onNewProblem: function () {
    Study.pcStuck = false;
    Study.stillSeconds = 0;
    Study.writtenSinceCheck = 0;
    Study.lastProgressAt = nowIso();
    Study.lastCheckAt = Date.now();
  },

  onSpeech: function (text) {
    if (Study.mode !== 'study' && /勉強(を)?(始め|はじめ|する|やる)|続き(を)?(やる|する|から)|^(うん、?)?やる[。!！]?$/.test(text)) { Study.start(); return true; }
    if (/休憩/.test(text)) { Study.pause('break'); return true; }
    if (/今日は(もう)?(終わり|おしまい)|勉強(を)?(終わ|おしまい)|^(終わり|おしまい)[。!！]?$/.test(text)) { Study.end(); return true; }
    if (Study.mode === 'study' && Teacher.choose(text)) return true; // 何をやるかを選んでいる
    if (Study.awaitingHintReply && secondsSince(Study.awaitingHintReply) < 30) {
      if (/いらない|大丈夫|自分で|いい$/.test(text)) { Study.declined(); return true; }
      if (/お願い|いる|うん|ちょうだい|教えて/.test(text)) { Study.awaitingHintReply = null; Teacher.ask('hint', null, true); return true; }
    }
    // 問題を出してもらう
    if (/苦手/.test(text) && /問題|出して/.test(text)) { Teacher.newProblem('weak'); return true; }
    var wants = /出して|ちょうだい|ください|にして|がいい|やりたい/.test(text);
    if (wants && /(簡単|やさしい|易しい)(の|問題|め)|簡単に|やさしく/.test(text)) { Teacher.newProblem('next', { level: 'easier' }); return true; }
    if (wants && /難しい(の|問題)|難しめ|難しく/.test(text)) { Teacher.newProblem('next', { level: 'harder' }); return true; }
    var topic = /(.+?)の問題(を)?(出して|ちょうだい|ください|やりたい)/.exec(text);
    if (topic && !/^(次|別|べつ|ほか|他|この|その|今)$/.test(topic[1])) { Teacher.newProblem('topic', { topic: clip(topic[1], 60) }); return true; }
    if (/別の問題|別のこと|ほかの(問題|こと)/.test(text)) { Teacher.askTopic(); return true; }
    if (/問題(を)?(出して|ちょうだい|ください)|次の問題|次いこ|^次[。!！]?$/.test(text)) { if (Teacher.problem) Teacher.newProblem('next'); else Teacher.askTopic(); return true; }
    if (!Teacher.problem) {
      if (/ヒント|わから|分から|見て/.test(text)) { Teacher.ask('hint', text, true); return true; }
      return false;
    }
    // 今の問題について
    if (/答え(は)?(何|なに|なん)|答え(を)?(教えて|見せて|言って)/.test(text)) { Teacher.ask('answer', text, true); return true; }
    var ans = /答えは[、,\s]*(.+)$/.exec(text);
    if (ans) { Teacher.answer(ans[1]); return true; }
    if (/ヒント/.test(text)) { Teacher.ask('hint', null, true); return true; }
    if (/わから|分から|説明して|どうやって|なんで|どうして/.test(text)) { Teacher.ask('explain', text, true); return true; }
    if (/見て|合ってる|あってる|できた/.test(text)) { Teacher.check('request'); return true; }
    return false;
  },

  declined: function () {
    Study.awaitingHintReply = null;
    var r = Memory.updateRelation({ hintDeclines: Memory.relation().hintDeclines + 1 });
    Memory.remember('hint_declined', Teacher.problem ? clip(Teacher.problem.text, 40) : '', 'conversation');
    Voice.say('わかった、自分でやってみて');
    log('hint declined; next time wait longer (declines ' + r.hintDeclines + ')');
  },

  // ---- 観測 (毎秒。軽いことだけ) ----
  sampleHands: function () {
    if (!HAS.hands || store.get('input.mode') !== 'hands' || !store.get('input.right.handTracked')) {
      Study.handsKnown = false; // 手が見えない = 判定を保留 (仕様 5.4 の「不明」)
      Study.lastHand = null;
      return;
    }
    var tip = hands.joint('right', 'indexTip');
    if (!tip) { Study.handsKnown = false; Study.lastHand = null; return; }
    Study.handsKnown = true;
    if (Study.lastHand) {
      var dx = tip.x - Study.lastHand.x, dy = tip.y - Study.lastHand.y, dz = tip.z - Study.lastHand.z;
      var speed = Math.sqrt(dx * dx + dy * dy + dz * dz); // 1 秒あたり (このスクリプトは 1 秒ごと)
      Study.writing = speed > 0.004 && speed < 0.15;
      Study.stillSeconds = speed <= 0.004 ? Study.stillSeconds + 1 : 0;
      if (Study.writing) {
        Study.writtenSinceCheck += 1;
        Study.lastProgressAt = nowIso();
      }
    }
    Study.lastHand = { x: tip.x, y: tip.y, z: tip.z };
  },

  // 書いたあとで手が止まった瞬間 (ノートが手で隠れにくい) に、見ている机の部分だけを撮って PC の先生に見せる (仕様 18.4)
  // PC の LLM を占めないように: 前の確認から max(45 秒, 前の確認にかかった時間の 3 倍) あけ、そのあいだに書いたときだけ。
  // ほかの用事 (声・ヒント・採点・問題) が走っている・待っている・声を文字にしている間はしない
  lastCheckSeconds: 0,
  lastCheckEndAt: 0,
  checkGap: function () { return Math.max(45, 3 * Study.lastCheckSeconds) * 1000; },
  maybeCheck: function () {
    if (!Teacher.problem || Teacher.solved || !PC.online || !Llm.idle() || Desk.capturing) return;
    if (Net.isBusy('stt') || Ears.pending || Teacher.choosing) return;
    if (!Study.handsKnown || Study.stillSeconds < 4 || Study.writtenSinceCheck < 3) return;
    if (Date.now() - Math.max(Study.lastCheckAt, Study.lastCheckEndAt) < Study.checkGap() || Voice.speaking) return;
    if (!Desk.lookingDown()) return;
    Study.lastCheckAt = Date.now();
    Study.writtenSinceCheck = 0;
    Teacher.check('pause');
  },

  // ---- いつ話しかけるか (仕様 6.4。Lev があれば候補の順位を Lev に任せる) ----
  state: function () {
    var r = Memory.relation();
    var wait = 25 + 15 * Math.min(4, r.hintDeclines); // 断られた経験があるほど長く待つ (仕様 7.4)
    var noProgress = Math.min(secondsSince(Study.lastProgressAt), 9999);
    var stuck = Math.min(1, 0.5 * Study.stillSeconds / wait + 0.4 * noProgress / (wait * 3) + (Study.pcStuck ? 0.3 : 0));
    return {
      studying: Study.mode === 'study',
      observed: Study.handsKnown && Desk.lookingDown(),
      writing: Study.writing,
      stillSeconds: Study.stillSeconds,
      secondsWithoutProgress: Math.round(noProgress),
      problemKnown: !!Teacher.problem,
      stuck: Math.round(stuck * 100) / 100,
      waitSeconds: wait,
      sinceLastIntervention: Math.round(Math.min(secondsSince(Study.lastIntervention), 9999)),
      quiet: Voice.quiet,
      hintDeclines: r.hintDeclines,
    };
  },

  allowed: function (s) {
    // 集中を守る決まり (Lev の点数より先に効く)
    var out = ['SILENT', 'OBSERVE'];
    if (!s.studying || !s.observed || s.quiet || s.writing || !PC.online) return out;
    if (s.sinceLastIntervention < 60) return out;
    if (s.stuck >= 0.6) out.push('ASK');
    if (s.stuck >= 0.6 && s.problemKnown) out.push('HINT');
    if (s.stuck < 0.3 && s.secondsWithoutProgress < 20) out.push('ENCOURAGE');
    return out;
  },

  decide: function () {
    if (Study.mode !== 'study' || Study.decisionPending || Date.now() < Study.nextDecisionAt) return;
    if (Voice.speaking || Study.awaitingHintReply || Llm.busy) return;
    var s = Study.state();
    var allowed = Study.allowed(s);
    if (allowed.length <= 2) return; // 黙る・見る しか許されていない
    var blocked = CANDIDATES_STUDY.filter(function (c) { return allowed.indexOf(c) < 0; });
    var rule = allowed.indexOf('ASK') >= 0 ? 'ASK' : 'OBSERVE';
    var report = function (chosen, scores, by, reason) {
      Report.event('decision', { lane: 'study', state: s, candidates: allowed, blocked: blocked, scores: scores, chosen: chosen, by: by, reason: reason });
    };
    Study.decisionPending = true;
    var gen = Teacher.gen;
    var started = Net.call('lev', { url: url('/decision/evaluate'), method: 'POST', json: { kind: 'study', state: s, candidates: allowed }, responseType: 'json', timeout: 8 }, function (r) {
      Study.decisionPending = false;
      if (Study.mode !== 'study' || gen !== Teacher.gen) return; // その間に状況が変わった
      var scores = r.ok && r.json && r.json.scores;
      if (!scores) { report(rule, null, 'rules', 'Lev が使えない (' + (r.json && r.json.error ? r.json.error.message : r.error || r.status) + ')'); Study.act(rule); return; } // Lev が落ちていても動く
      var best = allowed.slice().sort(function (a, b) { return (scores[b] || 0) - (scores[a] || 0); })[0];
      report(best, scores, 'lev', '迷っていそう ' + Math.round(s.stuck * 100) + '% / 手が止まって ' + s.stillSeconds + ' 秒 / 確信度 ' + Math.round((r.json.confidence || 0) * 100) + '%');
      Study.act(best);
    });
    if (!started) Study.decisionPending = false;
  },

  act: function (action) {
    // 黙る・見ると決めたら、しばらく決め直さない (毎秒 Lev に聞かない。仕様 8.5)
    Study.nextDecisionAt = Date.now() + (action === 'SILENT' || action === 'OBSERVE' ? 10000 : 30000);
    if (action === 'ASK') {
      if (Voice.offer('ヒントいる？')) {
        Study.lastIntervention = nowIso();
        Study.awaitingHintReply = nowIso();
        if (sisterHere()) attempt('faceUser', function () { scene.faceUser(CONFIG.character, 0.6); });
        later('ask.timeout', 21000, function () {
          if (Study.awaitingHintReply && secondsSince(Study.awaitingHintReply) >= 20) {
            // 無視された = 集中していたのか、聞き方が悪かったのかは分からない。間を空ける根拠にだけ使う (仕様 6.4)
            Study.awaitingHintReply = null;
            Memory.remember('ask_unanswered', '', 'microphone', 0.6);
          }
        });
      }
    } else if (action === 'HINT') {
      Study.lastIntervention = nowIso();
      Teacher.ask('hint', null, true);
    } else if (action === 'ENCOURAGE') {
      if (Voice.offer('いい感じ')) Study.lastIntervention = nowIso();
    }
  },
};

// PC の画面に出す「妹の今」
Report.status = function () {
  var s = Study.state();
  var r = Memory.relation();
  return {
    mode: Study.mode, modeText: { idle: '—', study: '勉強中', break: '休憩中' }[Study.mode],
    problem: Teacher.problem ? clip(Teacher.problem.text, 80) : null, problemId: Teacher.problem ? Teacher.problem.id : null,
    stuck: s.stuck, stillSeconds: s.stillSeconds, secondsWithoutProgress: Study.mode === 'study' ? s.secondsWithoutProgress : null,
    observed: s.observed, waitSeconds: s.waitSeconds, hintDeclines: s.hintDeclines, quiet: Voice.quiet,
    consentImages: Settings.get('consent.images', null), affinity: r.affinity,
    memory: Memory.enabled(), camera: Settings.get('camera', true), mic: Settings.get('mic', true), llmBusy: Llm.busy, llmBackground: Llm.bg, stage: Stage.last, stageKind: Stage.kind, micStatus: Stage.micStatus(), heard: Ears.heardCount,
  };
};

Study.hud();

// ==== 問題の板 (Quiz。仕様 6.7) ====
// PC の先生が出した問題 (教科・問題文。数式は Unicode の素の文字) を、紙のような板に出す。
// 机を見ていれば机の空いたところ (ノートの右) に寝かせて置き、無理なら目の前 0.75 m に立てて出す。
// 同じ問題の間は置き直さない。答え合わせの結果は下の行に出る。
var Board = {
  shownId: null,
  visible: false,

  show: function (problem) {
    if (!problem) return;
    store.set('quiz.tag', (problem.subject ? problem.subject : 'もんだい') + (problem.goal ? '  —  ' + clip(problem.goal, 26) : ''));
    store.set('quiz.footer', '声で「答えは …」  ·  「ヒント」  ·  「見て」');
    if (Board.shownId === problem.id && Board.visible) { store.set('quiz.text', clip(problem.text, 150)); return; }
    Board.shownId = problem.id;
    Board.place();
    store.set('quiz.text', '');
    // 書いていくように出る (reveal)
    later('board.text', 400, function () { if (Board.shownId === problem.id) store.set('quiz.text', clip(problem.text, 150)); });
  },

  place: function () {
    var onDesk = false;
    attempt('board.place', function () {
      var desk = Desk.gazePoint();
      if (desk && HAS.room && room.place('Quiz', 'table', 'gaze', 0.004, 'flat')) {
        // 机の空いているところ (ノートの横) に寄せる: 見ている点から 33 cm 右
        var p = viewer.pose();
        var rx = p.forward.z, rz = -p.forward.x; // 水平の右向き
        var len = Math.sqrt(rx * rx + rz * rz) || 1;
        scene.move('Quiz', 0.33 * rx / len, 0, 0.33 * rz / len);
        onDesk = true;
      }
    });
    if (!onDesk) attempt('board.front', function () { viewer.placeInFront('Quiz', 0.75, true); });
    scene.setVisible('Quiz', true);
    Board.visible = true;
  },

  // 問題の代わりに、聞いていることを出す (何をやるか・続けるか)。マイクが無くても、見れば分かるように
  prompt: function (tag, text, footer) {
    store.set('quiz.tag', tag);
    store.set('quiz.text', clip(text, 150));
    store.set('quiz.footer', footer || '');
    if (Board.shownId !== 'prompt' || !Board.visible) { Board.shownId = 'prompt'; Board.place(); }
  },

  // 問題を待っている間 (板がまだ無ければ出さない)
  waiting: function (text) {
    if (!Board.visible) return;
    if (text) store.set('quiz.footer', text);
    else if (Teacher.problem) store.set('quiz.footer', Teacher.solved ? '正解！' : '声で「答えは …」  ·  「ヒント」  ·  「見て」');
  },

  footer: function (text) { store.set('quiz.footer', text); },

  hide: function () {
    Board.visible = false;
    Board.shownId = null;
    attempt('board.hide', function () { scene.setVisible('Quiz', false); });
  },
};

// ==== 部屋にいる (仕様 3.2 / 4.2〜4.5 / 7.5 / 7.6 / 2.3) ====
// 妹の席は、シーンの小さな印 "Seat" を空間アンカーに留めて覚える (room.pin)。
// 座標を数字で覚えると、次に起動したときに原点が変わってずれる。アンカーなら同じ場所に戻る (仕様 4.3)。
// 歩く動き (FBX) は入れていないので、席・机の横・呼ばれた所へは歩かずにその場に現れる (滑って動くより自然で確実)。
// 現れる先は、床があり・家具の中でなく・ユーザーに近すぎない所だけ。だめならその場にいる。
var SEAT_HIDDEN_Y = -10; // シーンでの Seat の置き場所 (床の下)。アンカーが戻らなければここのまま

var Presence = {
  greeted: false,
  gazeSeconds: 0,
  lastTouch: 0,
  arrived: false,
  unmountedAt: 0,
  nextPlayAt: Date.now() + 90000,
  playing: false,
  playId: 0,
  PLAY_LABELS: ['table', 'storage', 'couch', 'bed', 'plant', 'lamp'],

  seatPosition: function () {
    var p = scene.getPosition('Seat');
    return p && p.y > SEAT_HIDDEN_Y + 5 ? p : null;
  },

  // そこに立てるか: 真上から下へ当てて最初が床 / ユーザーから 0.6 m 以上 / (from があれば) 途中に何も無い
  spotFree: function (x, z, from) {
    if (!HAS.room || !room.ready()) return false;
    var head = viewer.pose();
    if (!head) return false;
    var down = room.raycast(x, head.y + 0.3, z, 0, -1, 0, 'any');
    if (!down || !down.hit || String(down.label).toLowerCase() !== 'floor') return false;
    var ux = x - head.x, uz = z - head.z;
    if (ux * ux + uz * uz < 0.6 * 0.6) return false;
    if (from) {
      var dx = x - from.x, dz = z - from.z;
      var dist = Math.sqrt(dx * dx + dz * dz);
      if (dist > 0.05) {
        var ray = room.raycast(from.x, down.y + 0.3, from.z, dx / dist, 0, dz / dist, 'any');
        if (ray && ray.hit && ray.distance < dist + 0.25) return false; // 途中か、着いた所のすぐ先に何かある
      }
    }
    return true;
  },

  // そこに現れる (床の高さに置いてこちらを向く)。立てない所なら動かない: false
  appearAt: function (x, z) {
    var id = CONFIG.character;
    if (!sisterHere() || !Presence.spotFree(x, z, null)) { log('appear: spot not free; staying'); return false; }
    var head = viewer.pose();
    var floor = room.raycast(x, head.y, z, 0, -1, 0, 'floor');
    if (!floor || !floor.hit) return false;
    if (vrm.isWalking(id)) vrm.stop(id);
    scene.setPosition(id, floor.x, floor.y, floor.z);
    scene.faceUser(id);
    return true;
  },

  // 席が無いときの立ち位置: ユーザーの右斜め前 1.5 m (約 25°) の床。立てなければ、いちばん近い床
  standNearUser: function (id) {
    var p = viewer.pose();
    if (!p || !p.forward || !HAS.room) return false;
    var fx = p.forward.x, fz = p.forward.z;
    var len = Math.sqrt(fx * fx + fz * fz) || 1;
    fx /= len; fz /= len;
    var x = p.x + 1.35 * fx + 0.6 * fz, z = p.z + 1.35 * fz - 0.6 * fx;
    if (!Presence.spotFree(x, z, null)) return false;
    var floor = room.raycast(x, p.y, z, 0, -1, 0, 'floor');
    if (!floor.hit) return false;
    scene.setPosition(id, floor.x, floor.y, floor.z);
    return true;
  },

  // 覚えている席に戻る。無ければユーザーの近くの床に立つ
  arrive: function () {
    if (Presence.arrived || !sisterHere()) return;
    Presence.arrived = true;
    var id = CONFIG.character;
    var place = safe('arrive', function (seat) {
      if (seat) scene.setPosition(id, seat.x, seat.y, seat.z);
      else if (!Presence.standNearUser(id) && HAS.room) room.place(id, 'floor', 'nearest', 0);
      scene.faceUser(id);
      vrm.stopAnimation(id); // 力を抜いて立つ
      var r = Memory.updateRelation({ sessions: Memory.relation().sessions + 1, hintDeclines: Math.floor(Memory.relation().hintDeclines * 0.85 * 100) / 100 });
      Memory.remember('session_started', 'session ' + r.sessions + (seat ? ' (覚えた席)' : ''), 'app');
      var pinned = HAS.room && room.pinned('Seat');
      Report.event('session', { what: 'arrive', text: seat ? '覚えていた席に戻った' : (pinned ? '席のアンカーが見つからず、近くの床に立った' : '近くの床に立った (席はまだ決めていない)') });
      if (!seat && pinned) Hud.guide('前の席が見つかりません。B で決め直せます', 12);
    });
    if (!HAS.room || !room.pinned('Seat')) { place(null); return; }
    // アンカーは読み戻すのに少しかかる。最大 8 秒待つ
    var waited = 0;
    var tick = setInterval(safe('arrive.wait', function () {
      var seat = Presence.seatPosition();
      waited += 0.5;
      if (seat || waited >= 8) { clearInterval(tick); place(seat); }
    }), 500);
  },

  // 席を決める: 右コントローラーで床かソファを指して B
  setSeat: function () {
    if (!HAS.controller || !HAS.room) return;
    var a = controller.aim('right');
    if (!a || !a.tracked) { Hud.guide('右のコントローラーが見えていません', 6); return; }
    if (!room.ready()) { Hud.guide('部屋の準備がまだです (' + room.status() + ')。少し待ってからもう一度 B', 8); return; }
    // まず指した先の面 (ソファ・ベッドの座面も) に、だめなら床だけを狙い直す
    var hit = room.raycast(a.x, a.y, a.z, a.forward.x, a.forward.y, a.forward.z, 'any');
    if (!hit.hit || !hit.normal || hit.normal.y < 0.7) hit = room.raycast(a.x, a.y, a.z, a.forward.x, a.forward.y, a.forward.z, 'floor');
    if (!hit.hit || !hit.normal || hit.normal.y < 0.7) { Voice.say('そこには座れないかな。床を指してみて'); return; }
    Presence.stopPlay();
    scene.setPosition('Seat', hit.x, hit.y, hit.z);
    room.pin('Seat', safe('seat.pin', function (ok, detail) {
      if (!ok) { log('seat pin failed: ' + detail); Hud.guide('席を覚えられませんでした。見回してからもう一度 B', 8); }
      else Report.event('action', { what: 'seat', text: '席を決めた (' + (hit.label || '床') + ')。空間アンカーで覚えた' });
    }));
    if (!sisterHere()) return;
    // 席に現れてこちらを向く (ソファの上でも置ける)
    if (vrm.isWalking(CONFIG.character)) vrm.stop(CONFIG.character);
    scene.setPosition(CONFIG.character, hit.x, hit.y, hit.z);
    scene.faceUser(CONFIG.character, 0.8);
    Voice.say('ここ、わたしの席ね');
  },

  forgetSeat: function () {
    if (HAS.room) room.unpin('Seat');
    scene.setPosition('Seat', 0, SEAT_HIDDEN_Y, 0);
  },

  // 勉強を始めたら机の横へ: 右 0.8 m・前 0.3 m (約 70°、0.85 m)。真横 (90°) だと視野の外で、居るのに見えない
  sitBeside: function () {
    var p = viewer.pose();
    if (!p || !p.forward) return;
    var fx = p.forward.x, fz = p.forward.z;
    var len = Math.sqrt(fx * fx + fz * fz) || 1;
    fx /= len; fz /= len;
    Presence.appearAt(p.x + 0.8 * fz + 0.3 * fx, p.z - 0.8 * fx + 0.3 * fz);
  },

  // 呼ばれたら近くへ: 前 1.2 m・右 0.35 m (1.25 m。人と話すときの距離で、近すぎない)
  comeNear: function () {
    var p = viewer.pose();
    if (!p || !p.forward) return;
    var fx = p.forward.x, fz = p.forward.z;
    var len = Math.sqrt(fx * fx + fz * fz) || 1;
    fx /= len; fz /= len;
    Presence.stopPlay();
    Presence.appearAt(p.x + 1.2 * fx + 0.35 * fz, p.z + 1.2 * fz - 0.35 * fx);
  },

  pointAt: function (point) {
    if (!point || !sisterHere()) return;
    var id = CONFIG.character;
    vrm.lookAt(id, point.x, point.y, point.z);
    vrm.setHandTarget(id, 'right', point.x, point.y + 0.05, point.z);
    later('point.end', 3000, function () {
      if (!sisterHere()) return;
      vrm.clearHandTarget(id, 'right');
      vrm.clearLookAt(id);
    });
  },

  greet: function () {
    Presence.greeted = true;
    var r = Memory.relation();
    var last = r.lastSessionEnd;
    var line;
    // 見ていないこと (家に帰ってきた等) は言わない (仕様 3.5)
    if (last && secondsSince(last) < 36 * 3600) line = 'おかえり。今日も勉強やる？';
    else if (r.sessions > 1) line = 'あ、来た。ひさしぶり';
    else line = 'あ、来た。勉強するときは A か「勉強始める」って言ってね';
    if (!Voice.offer(line) && !Voice.quiet) Presence.greeted = false; // 話せなかった: 次に目が合ったときに
  },

  // ---- 近くの家具を触って遊ぶ (勉強していない・話していないときに、ときどき。設定「部屋を歩く」、最初は切) ----
  // 歩く動きが無いので、ユーザーが妹を見ていない間に家具の手前へ移ってから触る (目の前で滑っていかない)
  maybePlay: function () {
    if (Presence.playing || Date.now() < Presence.nextPlayAt) return;
    Presence.nextPlayAt = Date.now() + 90000 + Math.random() * 90000; // 1.5〜3 分おき
    var id = CONFIG.character;
    if (!Settings.get('play', false) || Study.mode === 'study' || !HAS.room || !sisterHere()) return;
    if (Voice.speaking || Curiosity.asking || Panel.open || !room.ready() || viewer.isLookingAt(id, 45)) return;
    var me = scene.getPosition(id);
    if (!me) return;
    var near = (room.list('any') || []).filter(function (o) {
      if (Presence.PLAY_LABELS.indexOf(o.label) < 0 || o.top == null || o.top > 1.3 || o.top < 0.25) return false;
      var d = Math.sqrt((o.x - me.x) * (o.x - me.x) + (o.z - me.z) * (o.z - me.z));
      return d > 0.7 && d < 3;
    });
    if (!near.length) return;
    var o = near[Math.floor(Math.random() * near.length)];
    // 家具の手前 (妹の側)、縁から 0.35 m の床に立つ
    var dx = me.x - o.x, dz = me.z - o.z;
    var len = Math.sqrt(dx * dx + dz * dz) || 1;
    dx /= len; dz /= len;
    var reach = Math.min(o.width || 0.6, o.depth || 0.6) / 2;
    var stand = { x: o.x + dx * (reach + 0.35), z: o.z + dz * (reach + 0.35) };
    if (!Presence.spotFree(stand.x, stand.z, null)) return; // 立てない: 今回はやめる
    // 触る所: 天面の、妹に近い側の縁から少し内側
    var touch = { x: o.x + dx * Math.max(0, reach - 0.12), y: o.top + 0.02, z: o.z + dz * Math.max(0, reach - 0.12) };
    Presence.playing = true;
    var myId = ++Presence.playId;
    var still = function () { return myId === Presence.playId && Presence.playing && sisterHere(); };
    later('play.watchdog', 25000, function () { if (still()) Presence.stopPlay(); }); // 何かが返ってこなくても 25 秒で終わる
    if (!Presence.appearAt(stand.x, stand.z)) { Presence.playing = false; return; }
    (function () {
      vrm.turnTo(id, touch.x, touch.z, 0.6, safe('play.turn', function () {
        if (!still()) return;
        vrm.lookAt(id, touch.x, touch.y, touch.z);
        vrm.setHandTarget(id, 'right', touch.x, touch.y + 0.06, touch.z);
        vrm.setExpression(id, 'relaxed', 40);
        // とん、とん (手を少し上げ下げする)
        later('play.tap1', 700, function () { if (still()) vrm.setHandTarget(id, 'right', touch.x, touch.y, touch.z); });
        later('play.tap2', 1200, function () { if (still()) vrm.setHandTarget(id, 'right', touch.x, touch.y + 0.07, touch.z); });
        later('play.tap3', 1700, function () { if (still()) vrm.setHandTarget(id, 'right', touch.x, touch.y, touch.z); });
        later('play.end', 3200, function () { if (still()) Presence.stopPlay(); });
        Report.event('action', { what: 'play', text: ({ table: '机', couch: 'ソファ', bed: 'ベッド', storage: '棚', plant: '植木', lamp: 'ランプ' }[o.label] || '家具') + 'を触って遊んだ' });
      }));
    })();
  },

  // 遊ぶのをやめる (勉強が始まった・呼ばれた・席を決めた・外した)。歩いていれば止める
  stopPlay: function () {
    if (!Presence.playing) return;
    Presence.playing = false;
    Presence.playId++;
    if (!sisterHere()) return;
    var id = CONFIG.character;
    attempt('stopPlay', function () {
      if (vrm.isWalking(id)) vrm.stop(id);
      vrm.clearHandTarget(id, 'right');
      vrm.clearLookAt(id);
      vrm.setExpression(id, 'relaxed', 0);
    });
  },

  // 1 秒ごと: 見られている・触られている
  tick: function () {
    var id = CONFIG.character;
    if (!sisterHere()) return;
    if (viewer.isLookingAt(id, 12)) {
      Presence.gazeSeconds += 1;
      if (!Presence.greeted && Presence.arrived && Presence.gazeSeconds >= 1) Presence.greet();
      // しばらく顔を見られていたら照れて目をそらす (目が合った、とは言わない: 仕様 7.5)
      if (Presence.gazeSeconds === 4 && Study.mode !== 'study' && !Presence.playing) {
        vrm.setExpression(id, 'relaxed', 60);
        var p = viewer.pose();
        if (p) vrm.lookAt(id, p.x + 1, p.y - 0.3, p.z);
        later('gaze.away', 1500, function () { if (sisterHere()) { vrm.clearLookAt(id); vrm.setExpression(id, 'relaxed', 0); } });
      }
    } else {
      Presence.gazeSeconds = 0;
    }
    // 手で頭に触れた (手が追跡できていないときは何もしない: 仕様 7.6)
    if (!HAS.hands || !store.get('input.right.handTracked') || Date.now() - Presence.lastTouch < 8000) return;
    var head = vrm.bonePosition(id, 'Head');
    var tip = head ? hands.joint('right', 'indexTip') : null;
    if (!tip) return;
    var dx = tip.x - head.x, dy = tip.y - head.y, dz = tip.z - head.z;
    if (dx * dx + dy * dy + dz * dz < 0.15 * 0.15) {
      Presence.lastTouch = Date.now();
      vrm.setExpression(id, 'happy', 70);
      later('touch.off', 2000, function () { if (sisterHere()) vrm.setExpression(id, 'happy', 0); });
      if (Study.mode !== 'study') Voice.offer('なに〜？');
      Memory.updateRelation({ affinity: Memory.relation().affinity + 0.01 });
      Report.event('observation', { what: 'touch', text: '頭に手が触れた (手の追跡)' }, 0.8, 'hand_tracking');
    }
  },
};

if (HAS.room) room.onReady(safe('room.ready', function () { Presence.arrive(); }));
// 部屋が読めない (スペースの設定をしていない等) ときも 15 秒で出てくる
later('arrive.fallback', 15000, function () { if (!Presence.arrived) { log('room not ready after 15 s; arriving without it'); Presence.arrive(); } });

if (HAS.controller) {
  controller.on('right.b.down', safe('right.b', function () { Presence.setSeat(); }));
  controller.on('right.a.down', safe('right.a', function () { if (Study.mode === 'study') Study.end(); else Study.start(); }));
}

// ヘッドセットを外したら止めて保存。外していた間のことは知らない (仕様 2.3)。かぶったら、外したところから続ける
if (HAS.headset) {
  headset.on('unmounted', safe('headset.unmounted', function () {
    Presence.unmountedAt = Date.now();
    Study.pause('headset_off');
    Presence.stopPlay();
    PC.setWearing(false);
    Mic.apply(); // 外している間はマイクも止める (仕様 2.3-4)
    Memory.updateRelation({ lastSessionEnd: nowIso() });
    Memory.remember('session_paused', 'headset removed', 'headset_sensor');
    storage.save();
    Report.flush();
  }));
  headset.on('mounted', safe('headset.mounted', function () {
    var away = Presence.unmountedAt ? (Date.now() - Presence.unmountedAt) / 1000 : 0;
    Presence.unmountedAt = 0;
    PC.setWearing(true);
    Mic.apply();
    PC.nextCheckAt = 0;       // PC をすぐ確かめる
    Teacher.nextSyncAt = 0;   // タブレットで進んだ問題も拾う
    Memory.remember('session_resumed', '', 'headset_sensor');
    if (Study.pausedBy === 'headset_off') later('resume', 1500, function () { if (Study.mode === 'break' && Study.pausedBy === 'headset_off') Study.start(); });
    else if (away > 30 * 60) Presence.greeted = false; // 長く外していたら、もう一度だけあいさつ
  }));
}

Hud.guide('A: 勉強   B: 妹の席   メニュー: 設定   声:「ヒント」「答えは…」', 40);

// ==== 気になる物 (仕様 18 / 19 / 27.1。「質問する」を決まった引き金にしない) ====
// 観測 → 関心を保留 → 区切りで候補を比べる → 聞く / 眺める / 待つ / やめる。
// 机の上を見るのは勉強していないときだけ、3 分に 1 回まで (勉強中は PC の LLM を先生の用事に空けておく)。
// 関心は自然に消えることもある。経過は PC の画面に出る (QA-03)。
var CANDIDATES_CURIOSITY = ['ask_user', 'look_at', 'wait', 'drop_interest'];

var Curiosity = {
  lastGlance: Date.now(),
  lastConsider: 0,
  asking: null, // 今聞いている関心
  askTimer: null,

  interests: function () { return store.get('memory.interests') || []; },
  save: function (list) {
    // 増え続けないように: 終わった関心は新しい 20 件だけ残す
    var open = list.filter(function (i) { return i.status === 'pending' || i.status === 'asked'; });
    var closed = list.filter(function (i) { return !(i.status === 'pending' || i.status === 'asked'); }).slice(-20);
    store.set('memory.interests', closed.concat(open.slice(-20)));
  },

  // 机の上をたまに見る (勉強していない・ユーザーが机を見ている・LLM が空いているときだけ)
  glance: function () {
    if (Study.mode === 'study' || !PC.online || !Llm.idle() || Desk.capturing) return;
    if (Settings.get('consent.images', null) !== true) return; // 同意は勉強を始めたときに聞く (ここでは聞かない)
    if (Date.now() - Curiosity.lastGlance < 180000) return;
    if (!Desk.gazePoint()) return;
    Curiosity.lastGlance = Date.now();
    var point = Desk.gazePoint();
    Desk.photo(function (page) {
      if (!page) return;
      if (Study.mode === 'study') { Desk.sent(); return; }
      var known = Object.keys(store.get('memory.objects') || {}).slice(0, 30);
      var started = Llm.run('glance', {
        url: url('/v1/chat/completions'), method: 'POST', responseType: 'json', timeout: 40,
        json: { model: CONFIG.visionModel, max_tokens: 300, messages: [{ role: 'user', content: [
          { type: 'text', text: 'Objects on this desk. Reply JSON only: {"objects":[{"name_ja": string, "name_en": string, "familiar": bool (a common stationery/household item), ' +
            '"position": "left"|"center"|"right", "confidence": 0..1}]}. Already known by name: ' + known.join(', ') + '. Do not guess what something is used for.' },
          { type: 'image_url', image_url: { url: page } },
        ] }] },
      }, function (r) {
        Desk.sent();
        var seen = firstJson(replyText(r));
        if (seen && seen.objects && seen.objects.slice) Curiosity.onSeen(seen.objects.slice(0, 12), point);
      }, false);
      if (!started) Desk.sent();
    });
  },

  onSeen: function (objects, point) {
    var where = { left: '机の左', center: '机の真ん中', right: '机の右' };
    var list = Curiosity.interests();
    var fresh = [];
    Report.event('observation', { what: 'desk', objects: objects }, null, 'quest_rgb');
    objects.forEach(function (o) {
      if (!o || !o.name_ja || (o.confidence || 0) < 0.4) return;
      var name = clip(o.name_ja, 30);
      Memory.sawObject(name, where[o.position] || '机の上', o.confidence);
      var explained = Memory.episodes().some(function (e) { return e.event === 'object_explained' && String(e.detail).indexOf(name) === 0; });
      var existing = list.filter(function (i) { return i.name === name; })[0];
      if (existing) {
        // 再観察: 見続けているものは確かになり、関心が少し強まる (仕様 19.3)
        existing.seen = Math.min(20, (existing.seen || 1) + 1);
        existing.point = point;
        existing.lastSeen = nowIso();
        return;
      }
      if (!o.familiar && !explained) {
        // T0: 見慣れない物 → 関心を保留 (確かさが低いままでもよい)
        list.push({ name: name, nameEn: o.name_en ? clip(o.name_en, 40) : null, where: where[o.position] || '机の上', point: point, novelty: 1 - (o.confidence || 0) / 2,
          confidence: o.confidence, seen: 1, status: 'pending', created: nowIso(), lastSeen: nowIso() });
        fresh.push(name);
        Memory.remember('noticed_object', name, 'camera_vision', o.confidence);
      }
    });
    Curiosity.save(list);
    if (fresh.length && point && sisterHere()) {
      vrm.lookAt(CONFIG.character, point.x, point.y, point.z);
      later('curiosity.look', 2500, function () { if (sisterHere()) vrm.clearLookAt(CONFIG.character); });
      Report.event('action', { what: 'look', text: '見慣れない物 (' + fresh.join('、') + ') を見た。関心として保留' });
    }
  },

  // 区切りのとき (勉強していない・話していない) に、保留した関心をどうするか決める
  consider: function (force) {
    if (Study.mode === 'study' || Voice.speaking || Curiosity.asking || Voice.quiet || Net.isBusy('lev')) return;
    if (!force && Date.now() - Curiosity.lastConsider < 30000) return;
    Curiosity.lastConsider = Date.now();
    var list = Curiosity.interests();
    var pending = list.filter(function (i) { return i.status === 'pending' && !(i.retryAt && Date.now() < i.retryAt); });
    if (!pending.length) return;
    var top = pending.sort(function (a, b) { return b.novelty * (b.seen || 1) - a.novelty * (a.seen || 1); })[0];
    // 古くなった関心は自然に消える (しつこく聞かない: 仕様 19.6)
    if (secondsSince(top.created) > 3 * 24 * 3600) {
      top.status = 'dropped';
      Curiosity.save(list);
      Report.event('decision', { lane: 'curiosity', target: top.name, candidates: ['drop_interest'], chosen: 'drop_interest', by: 'rules', reason: '3 日たったので関心が消えた' });
      return;
    }
    // Lev は英語の状態を前提にしている (モデルカード)。英語名が無い古い記録だけ日本語のまま
    var state = { interest: top.nameEn || top.name, novelty: top.novelty, timesSeen: top.seen || 1, hoursSinceNoticed: Math.round(secondsSince(top.created) / 360) / 10,
      userStudying: false, userJustFinishedStudying: !!Study.startedAt && Study.mode !== 'study', recognitionConfidence: top.confidence };
    var choose = function (best, scores, by, reason) {
      if (Study.mode === 'study' || Curiosity.asking || Voice.speaking) return; // その間に状況が変わった
      Report.event('decision', { lane: 'curiosity', target: top.name, state: state, candidates: CANDIDATES_CURIOSITY, scores: scores, chosen: best, by: by, reason: reason });
      if (best === 'ask_user') {
        Curiosity.asking = top;
        top.status = 'asked';
        Curiosity.save(list);
        // 位置が確かでないときは指差さない (仕様 20.2 / QA-05)
        if (top.point && (top.confidence || 0) >= 0.6) Presence.pointAt(top.point);
        else if (top.point && sisterHere()) vrm.lookAt(CONFIG.character, top.point.x, top.point.y, top.point.z);
        Voice.say('ねえ、' + top.where + 'にある' + top.name + 'みたいなの、あれなに〜？');
        Memory.remember('asked_about_object', top.name, 'self');
        // 30 秒答えが無ければ聞くのをやめる。次に聞くのは 10 分後、2 回答えてもらえなければ諦める (しつこく聞かない: 仕様 19.6)
        if (Curiosity.askTimer) clearTimeout(Curiosity.askTimer);
        Curiosity.askTimer = later('curiosity.timeout', 30000, function () {
          Curiosity.askTimer = null;
          if (Curiosity.asking !== top) return;
          Curiosity.asking = null;
          if (sisterHere()) vrm.clearLookAt(CONFIG.character);
          top.ignored = (top.ignored || 0) + 1;
          top.status = top.ignored >= 2 ? 'dropped' : 'pending';
          top.retryAt = Date.now() + 10 * 60 * 1000 * top.ignored;
          Curiosity.save(Curiosity.interests().map(function (i) { return i.name === top.name ? top : i; }));
          Report.event('decision', { lane: 'curiosity', target: top.name, candidates: ['wait', 'drop_interest'], chosen: top.status === 'dropped' ? 'drop_interest' : 'wait', by: 'rules', reason: '答えが無かった (' + top.ignored + ' 回目)' });
        });
      } else if (best === 'drop_interest') {
        top.status = 'dropped';
        Curiosity.save(list);
      } else if (best === 'look_at' && top.point && sisterHere()) {
        vrm.lookAt(CONFIG.character, top.point.x, top.point.y, top.point.z);
        later('curiosity.look', 3000, function () { if (sisterHere()) vrm.clearLookAt(CONFIG.character); });
      }
    };
    var rule = top.novelty > 0.6 || (top.seen || 1) >= 2 ? 'ask_user' : 'look_at';
    if (!PC.online) { choose(rule, null, 'rules', 'PC に届かないので端末の決まりで'); return; }
    var started = Net.call('lev', { url: url('/decision/evaluate'), method: 'POST', responseType: 'json', timeout: 8,
      json: { kind: 'curiosity', state: state, candidates: CANDIDATES_CURIOSITY } },
    function (r) {
      var scores = r.ok && r.json && r.json.scores;
      if (!scores) { choose(rule, null, 'rules', 'Lev が使えない'); return; }
      choose(CANDIDATES_CURIOSITY.slice().sort(function (a, b) { return (scores[b] || 0) - (scores[a] || 0); })[0], scores, 'lev',
        top.name + ' を ' + (top.seen || 1) + ' 回見た (確信度 ' + Math.round((r.json.confidence || 0) * 100) + '%)');
    });
    if (!started) Curiosity.lastConsider = 0;
  },

  // 答えを覚える (訂正できる記憶として。次からは聞かない)
  onSpeech: function (text) {
    if (!Curiosity.asking) return false;
    var item = Curiosity.asking;
    Curiosity.asking = null;
    if (Curiosity.askTimer) { clearTimeout(Curiosity.askTimer); Curiosity.askTimer = null; }
    var list = Curiosity.interests();
    list.forEach(function (i) { if (i.name === item.name) i.status = 'resolved'; });
    Curiosity.save(list);
    Memory.remember('object_explained', item.name + ': ' + text, 'user', 1);
    if (sisterHere()) vrm.clearLookAt(CONFIG.character);
    if (!PC.online) { Voice.say('へえ、そうなんだ。覚えとくね'); return true; }
    Voice.chat('さっき聞いた「' + item.name + '」について、ユーザーは「' + text + '」と答えた。短く反応して。', '', function (reply) {
      Voice.say(reply || 'へえ、そうなんだ。覚えとくね');
    });
    return true;
  },
};

// ==== 設定パネルと同意 (仕様 8.2 / 11.3 / 11.4 / 25) ====
// 左コントローラーのメニューボタン / Y (または「設定」と言う) で目の前に出る。
// カメラ・マイク・長い記憶・自分から話すか・部屋を歩くかを、それぞれ入り切りできる。覚えていることを見て、消せる。
// 画像を初めて送る前には、何を・どこへ送るかを見せて同意をもらう (勉強を始めたときに 1 回聞く)。

// ---- 同意 ----
var Consent = {
  asking: false,
  askedAt: 0,
  timer: null,

  // ノート・机の画像を PC へ送ってよいか。null = まだ聞いていない
  imagesAllowed: function () {
    if (!Settings.get('camera', true)) return false;
    if (!PC.online || !PC.allowImages) return false;
    var c = Settings.get('consent.images', null);
    if (c === null) { Consent.ask(); return false; }
    return c === true;
  },

  ask: function () {
    if (Consent.asking || Settings.get('consent.images', null) !== null) return;
    if (Consent.askedAt && Date.now() - Consent.askedAt < 10 * 60 * 1000) return; // 返事が無かったら 10 分は聞き直さない
    Consent.asking = true;
    Consent.askedAt = Date.now();
    store.set('consent.body',
      '勉強中に手が止まったときと、「ヒント」「見て」と言ったときに、見ている机の上 (50cm 四方) を撮って PC (' + shortServer() + ') に送ります。\n' +
      'PC の先生 (画像を読めるモデル) がノートを読んで、ヒントや答え合わせをします。写真は保存しません。\n' +
      '「設定」(左手メニュー) でいつでも止められます。');
    attempt('consent.show', function () { viewer.placeInFront('Consent', 0.9, true); scene.setVisible('Consent', true); });
    Voice.say('ノートの写真、PC の先生に見せてもいい？');
    // 返事が無いまま板を出しっぱなしにしない
    if (Consent.timer) clearTimeout(Consent.timer);
    Consent.timer = later('consent.timeout', 60000, function () {
      Consent.timer = null;
      if (!Consent.asking) return;
      Consent.asking = false;
      scene.setVisible('Consent', false);
    });
  },

  answer: function (yes) {
    Consent.asking = false;
    if (Consent.timer) { clearTimeout(Consent.timer); Consent.timer = null; }
    scene.setVisible('Consent', false);
    Settings.set('consent.images', yes);
    Memory.remember('consent', yes ? '画像を送ってよい' : '画像は送らない', 'user', 1);
    Report.event('session', { what: 'consent', text: yes ? '画像を PC へ送ることに同意' : '画像は送らない' });
    Voice.say(yes ? 'ありがと。読めないときは、読めたふりはしないね' : 'わかった。写真は送らないね。ヒントは声で聞いてくれたら答えるよ');
  },

  onSpeech: function (text) {
    if (!Consent.asking) return false;
    if (/いいよ|いい$|送って(いい|も)|見せて(いい|も)|うん|オッケー|OK/i.test(text)) { Consent.answer(true); return true; }
    if (/だめ|ダメ|いや|送らないで|やめて/.test(text)) { Consent.answer(false); return true; }
    return false;
  },
};

// ---- 設定パネル ----
var Panel = {
  open: false,
  confirm: null,     // 消すボタンは 2 回押して消す: { what, until }
  editingServer: false,

  show: function () {
    Panel.open = true;
    Panel.refresh();
    Panel.refreshMemory();
    Panel.closeServerEdit();
    attempt('panel.show', function () { viewer.placeInFront('Settings', 0.9, true); });
    scene.setVisible('Settings', true);
  },
  hide: function () {
    Panel.open = false;
    Panel.closeServerEdit();
    scene.setVisible('Settings', false);
  },
  toggle: function () { if (Panel.open) Panel.hide(); else Panel.show(); },

  refresh: function () {
    var on = function (key, fallback) { return Settings.get(key, fallback); };
    ui.setText('tglCamera', '写真を送る:  ' + (on('camera', true) ? (on('consent.images', null) === false ? '同意なし' : 'する') : 'しない'));
    var micSt = Stage.micStatus();
    ui.setText('tglMic', 'マイク:  ' + (!on('mic', true) ? '止める' : micSt === 'denied' ? '許可されていない' : micSt === 'noDevice' ? '無い' : '聞く'));
    ui.setText('tglMemory', '長い記憶:  ' + (on('memory', true) ? '残す' : '残さない'));
    ui.setText('tglTalk', '話しかける:  ' + (on('quiet', false) ? 'しない' : 'する'));
    ui.setText('tglPlay', '部屋を歩く:  ' + (on('play', false) ? 'する' : 'しない'));
    ui.setColor('tglCamera', on('camera', true) ? '#ffffff' : '#9aa3b8');
    ui.setColor('tglMic', on('mic', true) ? '#ffffff' : '#9aa3b8');
    ui.setColor('tglMemory', on('memory', true) ? '#ffffff' : '#9aa3b8');
    ui.setColor('tglTalk', on('quiet', false) ? '#9aa3b8' : '#ffffff');
    ui.setColor('tglPlay', on('play', false) ? '#ffffff' : '#9aa3b8');
    var state = PC.online ? '  ● 接続中' : PC.state === 'notFound' ? '  ● 見つからない' : '  ● 探しています';
    store.set('panel.server', 'PC: ' + shortServer() + state);
    ui.setColor('panelServer', PC.online ? '#7be0a6' : '#ffb86b');
    store.set('panel.inference', PC.online ? '推論  ' + PC.inferenceShort : 'PC で Cohabit PC を起動すると、自動でつながります');
  },
  refreshMemory: function () {
    if (!Panel.open) return;
    store.set('panel.memory', Memory.view(4));
  },

  // 消すのは 2 回押したとき (間違えて押しても消えない)
  askDelete: function (what, label) {
    if (Panel.confirm && Panel.confirm.what === what && Date.now() < Panel.confirm.until) {
      Panel.confirm = null;
      // 先に言ってから消す (「消したよ」という発言そのものを残さない)
      Voice.say(what === 'all' ? '全部忘れたよ。はじめまして、かな' : label + '、消したよ');
      Memory.forget(what);
      store.set('panel.note', label + 'を消しました');
      Panel.refresh();
      return;
    }
    Panel.confirm = { what: what, until: Date.now() + 5000 };
    store.set('panel.note', 'もう一度押すと「' + label + '」を消します (元に戻せません)');
  },

  // PC のアドレスを入れる (自動で見つからないときだけ。アプリの中のキーボード。設定パネルと入れ替わりに出る)
  editServer: function () {
    Panel.editingServer = true;
    store.set('panel.serverDraft', shortServer());
    scene.setVisible('Settings', false);
    attempt('address.show', function () { viewer.placeInFront('Address', 0.9, true); });
    scene.setVisible('Address', true);
  },
  closeServerEdit: function () {
    var was = Panel.editingServer;
    Panel.editingServer = false;
    scene.setVisible('Address', false);
    if (was && Panel.open) scene.setVisible('Settings', true);
  },
  submitServer: function () {
    var text = String(store.get('panel.serverDraft') || '').trim();
    if (!text) { Panel.closeServerEdit(); return; }
    PC.useAddress(text);
    Control.after = null;
    store.set('panel.note', 'PC のアドレスを ' + shortServer() + ' にしました。つながるか確かめています');
    Panel.closeServerEdit();
    Panel.refresh();
  },
};

// ---- ボタン (UI の bindingId がそのままイベント名。ui.on で 1 か所で受ける) ----
var UI_EVENTS = {
  setClose: function () { Panel.hide(); },
  setServer: function () { Panel.editServer(); },
  serverCancel: function () { Panel.closeServerEdit(); },
  'serverKb:submit': function () { Panel.submitServer(); },
  pcScan: function () { PC.rescan(); Control.after = null; store.set('panel.note', 'PC を探し直しています (20 秒くらい)'); Panel.refresh(); },
  tglCamera: function () {
    var next = !Settings.get('camera', true);
    Settings.set('camera', next);
    if (next && Settings.get('consent.images', null) === false) { Settings.set('consent.images', null); Consent.askedAt = 0; } // もう一度聞く
  },
  tglMic: function () { Settings.set('mic', !Settings.get('mic', true)); Mic.apply(); },
  tglMemory: function () { Settings.set('memory', !Settings.get('memory', true)); Panel.refreshMemory(); },
  tglTalk: function () { Voice.setQuiet(!Voice.quiet); },
  tglPlay: function () { var next = !Settings.get('play', false); Settings.set('play', next); if (!next) Presence.stopPlay(); },
  delToday: function () { Panel.askDelete('today', '今日の記憶'); },
  delRelation: function () { Panel.askDelete('relation', '妹との関係'); },
  delObjects: function () { Panel.askDelete('objects', '物の記録'); },
  delSeat: function () { Panel.askDelete('seat', '席'); },
  delAll: function () { Panel.askDelete('all', '全部の記憶'); },
  consentYes: function () { Consent.answer(true); },
  consentNo: function () { Consent.answer(false); },
};

Object.keys(UI_EVENTS).forEach(function (name) { ui.on(name, safe('ui ' + name, UI_EVENTS[name])); });

if (HAS.controller) {
  controller.on('left.menu.down', safe('left.menu', function () { Panel.toggle(); }));
  controller.on('left.y.down', safe('left.y', function () { Panel.toggle(); }));
}

store.set('panel.note', '');
Mic.apply(); // マイクは最初から聞く (設定で切れる。初回は端末が許可を聞く。開けなかったら「毎秒」が開き直す)
setInterval(safe('stage.tick', Stage.render), 300); // 字幕の上の 1 行 (音量と秒数を動かす)

// ---- PC の画面の操作ボタン (Cohabit PC → /control/next) ----
Control.on('study.start', function () { Study.start(); });
Control.on('study.break', function () { Study.pause('break'); });
Control.on('study.end', function () { Study.end(); });
Control.on('hint.ask', function () { Study.act('ASK'); });
Control.on('hint.give', function () { Teacher.ask('hint', null, true); });
Control.on('quiz.offer', function () { if (Study.mode !== 'study') Study.start(); else if (Teacher.problem) Teacher.newProblem('next'); else Teacher.askTopic(); });
Control.on('presence.come', function () { Presence.comeNear(); });
Control.on('curiosity.consider', function () { Curiosity.consider(true); });
Control.on('quiet.on', function () { Voice.setQuiet(true); });
Control.on('quiet.off', function () { Voice.setQuiet(false); });
Control.on('say', function (args) { if (args.text) Voice.say(String(args.text).slice(0, 200)); });

// ==== 1 秒ごと (interval 1000 ms) ====
// 観測 → 判断 → 行動 を回す。ここは軽いことだけ: 通信はそれぞれの中で間隔と「同時に 1 本」を守る。
// どの段も例外を外に出さない (1 つが失敗しても、ほかは動き続ける。ログは同じ場所 1 分に 1 回)。
var tickCount = (typeof tickCount === 'number' ? tickCount : 0) + 1;
attempt('tick.pc', PC.tick);
attempt('tick.mic', Mic.watch);
attempt('tick.presence', Presence.tick);
attempt('tick.play', Presence.maybePlay);
if (Study.mode === 'study') {
  attempt('tick.hands', Study.sampleHands);
  attempt('tick.check', Study.maybeCheck);
  attempt('tick.decide', Study.decide);
  attempt('tick.hud', Study.hud);
} else {
  attempt('tick.glance', function () { Curiosity.glance(); });
  attempt('tick.consider', function () { Curiosity.consider(false); });
}
attempt('tick.teacher', Teacher.tick);
if (tickCount % 2 === 0) attempt('tick.control', Control.poll);
if (tickCount % 4 === 0) attempt('tick.report', Report.flush);
if (Panel.open && tickCount % 5 === 0) attempt('tick.panel', Panel.refresh);
